window.__LEX={"G4500":"<h1>rhoizedon</h1>\n<p>Strong n° 4500 <i>Prononciation [hroyd-zay-don']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avec un fort bruit, avec un fracas strident</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥοιζηδόν</b>, <i>adv</i>., avec un bruit sifflant, <i>d’où</i> avec impétuosité, NIC. <i>Th. 556 ;</i> LYC. <i>66</i>.<br><span><b>Étym</b>. ῥοῖζος, -δον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ροιζηδον - ῥοιζηδόν</font>\n<br><br>vient d'un dérivé de rhoizos (un ronflement)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4501":"<h1>rhomphaia</h1>\n<p>Strong n° 4501 <i>Prononciation [hrom-fah'-yah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une grande épée</li>\n<li>en réalité un long javelot des soldats de Thrace, également une sorte de longue épée destinée à être portée sur l'épaule droite</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥομφαία, ας (ἡ)</b> large sabre à deux tranchants, <i>à l’usage des Thraces,</i> PLUT. <i>Æmil. 18 ; d’où en gén</i>. sabre, épée, SPT. <i>Gen. 3, 24, etc. ; fig</i>. NT. <i>Luc. 2, 35, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρομφαια - ῥομφαία</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G4502":"<h1>Rhouben</h1>\n<p>Strong n° 4502 <i>Prononciation [hroo-bane']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ruben (Angl. Reuben) = « voici un fils »\n<ol><li>enfant premier-né de Jacob par Léa</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρουβην</font> &lt; ראובן - <font face=\"Georgia\">Ῥουβήν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4503":"<h1>Rhouth</h1>\n<p>Strong n° 4503 <i>Prononciation [hrooth]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Ruth = « une amie »\n<ol><li>l'ancêtre de David et de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρουθ</font> &lt; רות - <font face=\"Georgia\">Ῥούθ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4504":"<h1>Rhouphos</h1>\n<p>Strong n° 4504 <i>Prononciation [hroo'-fos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rufus = « rouge »\n<ol>\n<li>nom d'un certain chrétien</li>\n<li>fils de Simon de Cyrène qui porta la croix</li>\n<li>peut-être le même que Paul fait saluer (<a class=\"ref\" data-r=\"ROM16.13\">Romains 16.13</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ῥοῦφος</b> <i>ou</i> (ὁ) = <i>lat</i>. Rŭfus, <i>n. d’h. rom</i>. PLUT. <i>T. Gracch. 19, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρουφος - Ῥοῦφος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4505":"<h1>rhume</h1>\n<p>Strong n° 4505 <i>Prononciation [hroo'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le balancement, la ruée, la force, la trace, d'un corps en mouvement</li>\n<li>une étendue de voie dans une ville limitée par des constructions sur les deux côtés</li>\n<li>une rue, une ruelle</li>\n</ol>\n</td>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥύμη, ης (ἡ)</b> <span>[ῡ]</span><br><b>   I</b> force <i>ou</i> vitesse d’un corps qui se meut, <i>d’où</i> mouvement impétueux, élan, vitesse, impétuosité, THC. <i>2, 76 ; en parl. d’ailes,</i> AR. <i>Pax 86, etc. ; de chevaux,</i> XÉN. <i>Cyr. 7, 1, 31 ; du mouvement du sang dans les veines,</i> HPC. <i>20, 29 ; d’un navire en mouvement,</i> ARSTT. <i>H.A. 4, 8, 12 ; fig. en parl. des passions,</i> DÉM. <i>546, 29 ; ou de la fortune :</i> τῆς τύχης, PLUT. <i>Cæs. 53,</i> mouvement favorable, <i>d’où en gén</i>. faveur de la fortune ;<br><b>   II</b> ligne tirée <i>ou</i> tracée, <i>d’où :</i><br><b>      1</b> rue d’une ville, PHILIPPID. (<i>Com. fr. 4, 471</i>) ;<br><b>      2</b> quartier d’un camp romain, POL. <i>6, 29, 1 ; d’où</i> compagnie de quartier, EN. TACT.<br><span><b>Étym</b>. ῥῦμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυμη - ῥύμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4506":"<h1>rhoumai</h1>\n<p>Strong n° 4506 <i>Prononciation [rhoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tirer à soi, délivrer, sauver</li>\n<li>le libérateur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥύομαι</b> <span>[υ <i>prés. et impf. ;</i> ῡ <i>f. et ao</i>. ATT.]</span> <span>(<i>impf</i>. ἐρρυόμην, <i>f</i>. ῥύσομαι, <i>ao</i>. ἐρρυσάμην, <i>pf. inus</i>.)</span> <i>aussi</i> <b>ἔρυμαι, ἐρύομαι :<br>      1</b> sauver, protéger, défendre, préserver : (βουλὴ) ἐρύσσεται ἠδὲ σαώσει, IL. <i>10, 44</i> (cette résolution les) défendra et les sauvera ; <i>avec l’acc. de la pers. ou de la chose sauvée :</i> τινα, IL. <i>15, 290 ;</i> HDT. <i>4, 187 ; 6, 7, etc. ;</i> ESCHL. <i>Sept. 302, 824 ; rar. en prose att. ou réc</i>. PLUT. <i>M. 834</i> d ; DL. <i>8, 79,</i> sauver qqn ; ῥυσθῆναι τῆς θυσίας, HLD. <i>10, 7,</i> (Chariclée) être sauvée d’un sacrifice ; <i>souv. avec une prép. :</i> τινα ὑπ' Ἀχαιῶν, IL. <i>17, 224,</i> sauver qqn des mains des Grecs, protéger contre les Grecs ; τινα ὑπὲκ κακοῦ, OD. <i>12, 107 ; ou</i> ἐκ θανάτου, LUC. <i>As. 33 ;</i> sauver qqn d’un malheur, de la mort ; <i>avec ἀπό et le gén</i>. SOPH. <i>O.R. 1352 ;</i> NT. <i>Matth. 6, 13 ; avec un inf. précédé ou non de</i> μή : τινα μὴ θανεῖν, EUR. <i>Or. 598 (cf</i>. HDT. <i>7, 11 ;</i> EUR. <i>H.f. 197), ou</i> τινα θανεῖν, EUR. <i>Alc. 11,</i> sauver de la mort ; <i>en parl. des dieux qui protègent les mortels,</i> IL. <i>15, 257, 290 ;</i> OD. <i>15, 35, etc. ;</i> ESCHL. <i>Sept. 90, etc. ; de princes ou de chefs qui défendent leurs villes et leurs peuples,</i> IL. <i>9, 396 ; de sentinelles qui gardent l’armée,</i> IL. <i>10, 417 ; de bergers qui gardent leurs troupeaux,</i> OD. <i>14, 107, etc. ; d’une servante, de chiens,</i> θύρας εἴρυσθαι, OD. <i>23, 229 ;</i> αὖλιν, THCR. <i>Idyl. 25, 76,</i> garder des portes, une cour ; <i>avec un suj. de ch. :</i> κυνέη ῥύεται κάρη, IL. <i>10, 259 (cf</i>. IL. <i>16, 799 ; 23, 819</i>) un casque protège sa tête ; <i>de même, en parl. d’un mur de défense,</i> IL. <i>12, 8 ;</i> ἄστυ πύργοι εἰρύσσονται, IL. <i>18, 275,</i> des tours protégeront la ville ; <i>d’un lieu sacré qui recueille qqn pour le protéger,</i> ESCHL. <i>Suppl. 509 ; avec l’acc. de la ch. dont on se libère :</i> ἔργῳ ἀγαθῷ τὰς αἰτίας, THC. <i>5, 63,</i> racheter ses fautes (<i>litt</i>. s’en libérer) par une noble action ;<br><b>      2</b> <i>d’où</i> masquer à la vue, cacher, voiler, <i>acc</i>. OD. <i>6, 129 ;</i><br><b>      3</b> conserver fidèlement, observer avec soin : φρεσίν (τι) OD. <i>16, 459,</i> conserver (qqe ch.) dans son esprit ; βουλὰς Κρονίωνος, IL. <i>21, 230,</i> observer les volontés du fils de Kronos ; ἔπος, IL. <i>1, 216,</i> respecter un ordre ;<br><b>      4</b> <i>d’où</i> prendre garde à, surveiller, observer : τινα, OD. <i>16, 463,</i> qqn ; <i>d’où</i> se rendre compte de, découvrir, <i>acc</i>. OD. <i>23, 82 ;</i><br><b>      5</b> écarter, éloigner, repousser, retenir (<i>syn. de</i> ἐρύκω) : <i>avec l’acc. de la pers. ou de la chose qu’on écarte :</i> ἔγχος, IL. <i>5, 538,</i> écarter une javeline ; Κῆρα, IL. <i>2, 859,</i> la mort ; Ἠῶ ἐπ' Ὠκεανῷ, OD. <i>23, 244,</i> retenir l’Aurore dans l’Océan ; νιν μάχας ἔργον κορύσσοντα, PD. <i>I. 8 (7) 114,</i> retenir (Achille) provoquant l’œuvre de la guerre ; <i>fig</i>. νόστον, PD. <i>N. 9, 29,</i> écarter, <i>càd</i>. rendre impossible le retour ; χόλον, IL. <i>24, 584,</i> contenir sa colère ; πᾶν μίασμα, SOPH. <i>O.R. 312,</i> écarter toute souillure.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. 3 sg</i>. ἔρυται <span>[ῡ]</span> A. RH. <i>2, 1208 ; opt. 3 pl. ion</i>. ῥυοίατο, HDT. <i>4, 135 ; 3 pl</i>. εἰρύαται <span>[ῠ]</span> IL. <i>1, 239, mais</i> <span>[ῡ]</span> OD. <i>16, 463 (p.-ê. pf.) ; inf. athématique</i> ῥῦσθαι (<i>thém</i>. ῥύεσθαι) IL. <i>15, 141 ;</i> εἴρυσθαι OD. <i>3, 268. Impf. 2 sg. athém</i>. ἔρυσο <span>[ῡ]</span> IL. <i>22, 507 ; 3 sg. athém</i>. ἔρυτο <span>[ῡ]</span> (<i>thém</i>. ἐρύετο) IL. <i>4, 138 ; 6, 403 ; 23, 819 ;</i> HÉS. <i>Sc. 415 ;</i> A. RH. <i>3, 1305, mais</i> ἔρυτο <span>[ῠ]</span> HÉS. <i>Th. 304 (pass</i>.) ; εἴρυτο <span>[ῡ]</span> HÉS. <i>Sc. 138 ; 3 sg. poét</i>. ῥύετο, IL. <i>16, 799 ; 2 pl</i>. ῥύεσθε, ESCHL. <i>Sept. 824 ; 3 pl</i>. ῥύοντο, PD. <i>I. 8, 114 ;</i> εἴρυντο, IL. <i>12, 454 ; 3 pl</i>. ῥύατο, IL. <i>18, 515 ;</i> OD. <i>17, 201 ;</i> εἰρύατο <span>[ῠ]</span> IL. <i>22, 303. Fut. épq. 2 sg</i>. ἐρύσσεαι, IL. <i>20, 311 ; 3 sg</i>. ἐρύσσεται, IL. <i>10, 44 ; 3 pl. dor</i>. ῥυσεῦνται, CALL. <i>L. Pall. 112. Ao</i>. ῥυσάμην <span>[ῠ]</span> IL. <i>15, 29 ; 3 sg</i>. ἐρύσατο <span>[ῡ]</span> IL. <i>2, 859, etc., ou sans augm</i>. ῥύσατο, OD. <i>23, 244, etc. ; ao.2 athém</i>. ἔρυτο <span>[ῡ]</span> SOPH. <i>O.R. 1352 ; 3 duel</i> ῥυσάσθην, IL. <i>14, 106 ; ao. réc</i>. ἐρρύσθην, DS. <i>21, 6 ;</i> HLD. <i>10, 7 Homonymes avec</i> ἐρύομαι¹ « tirer », <i>dont le contexte est différenciant</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *ueru-, *uruH-, repousser, défendre, <i>d’où</i> *ϝέρυμαι, *ϝέ-ϝρυ-ται (<i>p</i>. εἴρυται <span>[ῡ]</span>, <i>cf</i>. εἰρύαται <i>l. c.) ; cf. sscr</i>. varū-tár-, protecteur, vṛṇóti, défendre, <i>all</i>. wehren ; ἔρυμα, Ἐρύλαος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρουμαι - ῥύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n<br17 fois dans 15 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Romains (3)</li>\n<li>2 Corinthiens (3)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (3)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G4507":"<h1>rhuparia</h1>\n<p>Strong n° 4507 <i>Prononciation [hroo-par-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre sale, immonde, crasse, saleté</li>\n<li>souiller, déshonorer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥυπαρία, ας (ἡ)</b> <span>[ῠᾰρ]</span><br><b>      1</b> saleté, PLUT. <i>M. 60</i> d, <i>142</i> a ;<br><b>      2</b> <i>fig</i>. avarice sordide, CRITIAS (POLL. <i>3, 116</i>) ; TÉLÈS (STOB. <i>Fl. 97, 81) etc</i>.<br><span><b>Étym</b>. ῥυπαρός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυπαρια - ῥυπαρία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4508":"<h1>rhuparos</h1>\n<p>Strong n° 4508 <i>Prononciation [rhoo-par-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être sale, devenir immonde, obscène</li>\n<li>métaph. être souillé par l'iniquité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥυπαρός, ά, όν</b> <span>[ῠᾰ]</span><br><b>      1</b> sale, malpropre, ARTÉM. <i>2, 3 ; en parl. de métaux,</i> impur, DIOSC. <i>5, 84 ;</i> ἄρτος, POL. <i>37, 5, 12,</i> sorte de pain bis fait avec de la farine grossière ;<br><b>      2</b> <i>fig</i>. vil, trivial, commun, <i>en parl. du style,</i> LGN <i>43, 5</i>.<br><span>•<i> Cp</i>. ῥυπαρώτερος, EUP. <i>2-1, 551 Meineke</i>.<br><span><b>Étym</b>. ῥύπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυπαρος - ῥυπαρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4509":"<h1>rhupos</h1>\n<p>Strong n° 4509 <i>Prononciation [hroo'-pos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ce qui est immonde, sale, obscène</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ῥύπος, ου (ὁ)</b> <span>[ῠ]</span><br><b>      1</b> crasse, saleté, SIM. <i>fr. 6, 63 ;</i> ESCHL. <i>fr. 76 ;</i> PLAT. <i>Parm. 130</i> c ; POL. <i>23, 7, 8 ;</i> PLUT. <i>M. 82</i> b ; THCR. <i>Idyl. 15, 20 ; fig</i>. souillure, M. ANT. <i>7, 47 ;</i><br><b>      2</b> toute substance gluante, <i>d’où</i> poix <i>ou</i> cire pour cacheter, AR. <i>Lys. 1200 au plur</i>.<br><span><b>Étym</b>. <i>cf</i>. ῥύπον.</span><br><br>\n➁ <b>ῥύπος, εος-ους (τὸ)</b> petit-lait, HPC. <i>614, 54</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυπος - ῥύπος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4510":"<h1>rhupoo</h1>\n<p>Strong n° 4510 <i>Prononciation [rhoo-po'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre sale, souillé, immonde</li>\n<li>être souillé (moralement)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥυπαίνω</b> (<i>seul. prés. ; pass. seul. prés. et ao</i>. ἐρρυπάνθην) :<br><b>   I</b> tacher, salir, <i>d’où au pass</i>. être sale <i>ou</i> se salir, XÉN. <i>Lac. 11, 3 ;</i> NT. <i>Apoc. 22, 11 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> souiller, ARSTT. <i>Nic. 1, 8, 16, etc. ;</i><br><b>      2</b> outrager, insulter, PHÉRÉCR. (<i>Com. fr. 2, 352</i>).<br><span><b>Étym</b>. ῥύπος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυποω - ῥυπαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4511":"<h1>rhusis</h1>\n<p>Strong n° 4511 <i>Prononciation [hroo'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une perte, qui coule, flux, écoulement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ῥύσις, εως (ἡ)</b> <span>[ῠ]</span><br><b>   I</b> écoulement :<br><b>      1</b> écoulement d’eau, PLAT. <i>Leg. 944</i> b ; <i>particul</i>. cours d’un fleuve, POL. <i>2, 16, 6, etc. ;</i><br><b>      2</b> flux menstruel, HPC. <i>Aph. 1248 ; c</i>. γονόρροια, SPT. <i>Lev. 15, 2, etc. ;</i><br><b>      3</b> écoulement d’un liquide, <i>en gén</i>. HPC. <i>Aph. 1244 ;</i> ARSTT. <i>Meteor. 2, 2, 16, etc. ;</i><br><b>   II</b> <i>anal</i>. chute (<i>d’un fruit,</i> TH. <i>H.P. 4, 14, 10 ;</i> C. P. <i>1, 19, 5 ; des cheveux,</i> GAL. <i>2, 267, etc</i>.).<br><span><b>Étym</b>. ῥέω.</span><br><br>\n➁ <b>ῥύσις, εως (ἡ)</b> <span>[ῠ]</span> délivrance, SPT. <i>Sir. 51, 9</i>.<br><span><b>Étym</b>. ῥύομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυσις - ῥύσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4512":"<h1>rhutis</h1>\n<p>Strong n° 4512 <i>Prononciation [hroo-tece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une ride</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥυτίς, ίδος (ἡ)</b> <span>[ῠῐδ]</span> pli de la peau, ride, AR. <i>Pl. 1051 ;</i> ANTH. <i>5, 264 ; 6, 93 ; 7, 217 ;</i> PLAT. <i>Conv. 190</i> e, <i>191</i> a.<br><span><b><span class=\"arrow\"></span></b> <span>[ῡ]</span> NAZ. <i>v. Jacobs</i> ANTH. <i>p. 726</i>.<br><span><b>Étym</b>. ῥυσός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρυτις - ῥυτίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4513":"<h1>Rhomaikos</h1>\n<p>Strong n° 4513 <i>Prononciation [rho-mah-ee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Latin : « la force de Rome »\n<ol><li>le langage parlé par les Romains</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ῥωμαϊκός, ή, όν</b>, qui concerne Rome <i>ou</i> les Romains, romain, <i>d’où p. ext</i>. latin, POL. <i>11, 20, 6, etc. ;</i> PLUT. <i>Luc. 11, etc. ;</i> LUC. <i>M. cond. 24, etc</i>.<br><span>•<i> Cp</i>. -ώτερος, ANON. (<i>Cram. 3, 190, 30) ; sup</i>. -ώτατος, ANTH. <i>9, 502</i>.<br><span><b>Étym</b>. Ῥώμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρωμαικος - Ῥωμαϊκός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>","G4514":"<h1>Rhomaios</h1>\n<p>Strong n° 4514 <i>Prononciation [hro-mah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un résident de la cité de Rome, un citoyen Romain</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ῥωμαῖος, α, ον</b>, de Rome, Romain, POL. <i>7, 3, etc. ;</i> PLUT. <i>Mar. 40, etc. ;</i> οἱ Ῥωμαῖοι, DH. <i>1, 2, etc. ;</i> PLUT. <i>Popl. 13, etc</i>. les Romains ; τὰ Ῥωμαῖα, DC. <i>37, 8,</i> les jeux romains ; ὁ Ῥωμαῖος, DC. <i>72, 15,</i> le mois romain, <i>càd</i>. le mois de novembre <i>sous l’empereur Commode</i>.<br><span><b>Étym</b>. Ῥώμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρωμαιος - Ῥωμαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (11)</li>\n</ul>\n</td></tr>\n</table>","G4515":"<h1>Rhomaisti</h1>\n<p>Strong n° 4515 <i>Prononciation [hro-mah-is-tee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Latin : « la force de Rome »\n<ol><li>le langage parlé par les Romains</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥωμαϊστί</b>, <i>adv</i>., en langue romaine, en latin, PLUT. <i>Crass. 27, M. 318</i> d, <i>etc. ;</i> APP. <i>Mithr. 2, etc</i>.<br><span><b>Étym</b>. ῥωμαΐζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρωμαιστι - Ῥωμαϊστί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4516":"<h1>Rhome</h1>\n<p>Strong n° 4516 <i>Prononciation [hro'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Rome = « force »\n<ol><li>la célèbre capitale de l'ancien monde</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Ῥώμη, ης (ἡ) :<br>   I</b> <i>n. rom</i>. = <i>lat</i>. Rōma ; :<br><b>      1</b> Rome, <i>v. d’Italie,</i> ARSTT. <i>fr. 568 ;</i> PLUT. <i>Rom. 1, etc. ;</i><br><b>      2</b> Roma, <i>n. de f. myth</i>. PLUT. <i>Qu. rom. 6, Rom. 2, etc. ;</i><br><b>   II</b> <i>n. grec, n. de chienne,</i> XÉN. <i>Cyn. 7, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. Ῥώμα, ANTH. <i>9, 59 ;</i> A. PL. <i>72, etc</i>.<br><span><b>Étym</b>. I <i>lat</i>. Roma ; II ῥώμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Ρωμη - Ῥώμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (5)</li>\n<li>Romains (2)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4517":"<h1>rhonnumi</h1>\n<p>Strong n° 4517 <i>Prononciation [hrone'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre fort, fortifier, renforcer</li>\n<li>être fort, prospérer</li>\n<li>formule usuelle pour terminer une lettre, adieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ῥώννυμι</b> <span>[ῡ]</span> <span>(<i>impf</i>. ἐρρώννυν, <i>ao</i>. ἔρρωσα, <i>f. et pf. inus. ; pass</i>. ῥώννυμαι, <i>f</i>. ῥωσθήσομαι, <i>ao</i>. ἐρρώσθην, <i>pf</i>. ἔρρωμαι, <i>pl.q.pf</i>. ἐρρώμην)</span><br><b>   I</b> fortifier, <i>acc</i>. HPC. <i>380, 42 ; fig</i>. PLUT. <i>Per. 19, etc. ;</i><br><b>   II</b> <i>pass</i>. ῥώννυμαι <span>(<i>ao</i>. ἐρρώσθην, <i>pf</i>. ἔρρωμαι <i>au sens d’un prés., pl.q.pf</i>. ἐρρώμην <i>au sens d’un impf</i>.)</span> être fort, vigoureux, THC. <i>7, 15 ;</i> EUR. <i>Her. 636, etc. ;</i> PLUT. <i>Cor. 24 ; particul. au pf. et au pl.q.pf. :</i><br><b>      1</b> être dans toute sa force, XÉN. <i>Hell. 3, 4, 29 ; fig</i>. ῥ. χρήμασιν, PLUT. <i>Popl. 23,</i> être puissant par ses ressources ; <i>part</i>. ἐρρωμένος, η, ον, fort, robuste ;<br><b>      2</b> avoir la force de, <i>avec l’inf</i>. PLAT. <i>Conv. 176</i> b ;<br><b>      3</b> faire tous ses efforts, THC. <i>2, 8 ; cf</i>. THC. <i>6, 17 ;</i> LYS. <i>132, 32 ;</i><br><b>      4</b> <i>particul. comme formule d’adieu dans une lettre :</i> ἔρρωσο, XÉN. <i>Cyr. 4, 5, 33,</i> portez-vous bien, adieu ! ἐρρῶσθαί τινι φράζειν <i>ou</i> εἰπεῖν, PLAT. <i>Phæd. 61</i> b ; DÉM. <i>278, 6 ; etc</i>. dire à qqn de se bien porter, <i>càd</i>. faire ses adieux à qqn ; <i>souv. avec ironie, càd</i>. envoyer promener qqn ; πολλὰ ἐρρῶσθαι εἰπὼν τοῖς νόμοις καὶ ὑμῖν, DÉM. <i>419, 12,</i> ayant fait force compliments à vous et aux lois, <i>càd</i>. ayant envoyé promener les lois et vous.<br><span><b>Étym</b>. <i>incert. ; v</i>. ῥώομαι ; <i>cf</i>. ἐρρωμένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ρωννυμι - ῥώννυμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4518":"<h1>sabachthani</h1>\n<p>Strong n° 4518 <i>Prononciation [sab-akh-than-ee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tu m'as abandonné</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαβαχθανι</font> &lt; עזבתני - <font face=\"Georgia\">σαβαχθάνι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Transcription Araméenne</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4519":"<h1>sabaoth</h1>\n<p>Strong n° 4519 <i>Prononciation [sab-ah-owth']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>sabaoth : « des armées »\n<ol>\n<li>Le Seigneur des armées\n<ol type=\"a\">\n<li>Seigneur des armées d'Israël, celles qui sont sous le haut commandement et la protection de l'Eternel, qui défend leur cause dans la guerre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαβαωθ</font> &lt; צבאות - <font face=\"Georgia\">Σαβαώθ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4520":"<h1>sabbatismos</h1>\n<p>Strong n° 4520 <i>Prononciation [sab-bat-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un sabbat respecté (gardé)</li>\n<li>le repos béni sans labeur ni difficulté, considéré comme à venir par les vrais adorateurs de Dieu et les vrais Chrétiens</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαϐϐατισμός, οῦ (ὁ)</b> <span>[ϐᾰ]</span> célébration du sabbat, PLUT. <i>M. 166</i> a ; NT. <i>Hebr. 4, 9</i>.<br><span><b>Étym</b>. σαϐϐατίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαββατισμος - σαββατισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4521":"<h1>sabbaton</h1>\n<p>Strong n° 4521 <i>Prononciation [sab'-bat-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le septième jour de chaque semaine qui était une fête sacrée, pour lequel les Israélites devaient s'abstenir de tout travail\n<ol type=\"a\">\n<li>l'institution du sabbat, la loi pour garder saint le septième jour de la semaine</li>\n<li>un sabbat, un jour de sabbat</li>\n</ol>\n</li>\n<li>sept jours, une semaine</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάϐϐατον, ου (τὸ)</b> <span>[ϐᾰ]</span><br><b>      1</b> le sabbat, <i>jour de repos chez les Juifs,</i> JOS. <i>A.J. 1, 1, 1 ;</i> NT. <i>Luc. 13, 14, etc. ; au pl</i>. τὰ σάϐϐατα, NT. <i>Matth. 28, 1 ; Marc. 2, 23, etc. m. sign. ;</i><br><b>      2</b> <i>p. ext. au pl</i>. τὰ σάϐϐατα, la semaine, NT. <i>Matth. 28, 1 ; Marc. 16, 2 et 9 ; Luc. 18, 12, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. irrég</i>. σάϐϐασι, ANTH. <i>5, 160</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαββατον</font> &lt; שבת - <font face=\"Georgia\">σάββατον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n68 fois dans 62 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (12)</li>\n<li>Luc (20)</li>\n<li>Jean (13)</li>\n<li>Actes (10)</li>\n<li>1 Corinthiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4522":"<h1>sagene</h1>\n<p>Strong n° 4522 <i>Prononciation [sag-ay'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un grand filet de pêche, un filet à draguer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαγήνη, ης (ἡ)</b> <span>[ᾰ]</span><br><b>      1</b> seine, <i>grand filet de pêcheur,</i> PLUT. <i>M. 169</i> c ; LUC. <i>Tim. 22, etc. ;</i><br><b>      2</b> <i>p. ext</i>. filet de chasseur, BABR. <i>43, 8</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαγηνη - σαγήνη</font>\n<br><br>vient d'un dérivé de satto (équiper) du sens de fourniture, spécialement une selle de transport (qui en Orient est simplement un sac ou de la corde tressée)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – semble être le mot le plus général pour les filets de toute sorte\n<br><br> – un filet de pêche, filet à lancer, généralement en forme de poire\n<br><br> – un filet de pêche, une seine ou un filet à draguer</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4523":"<h1>Saddoukaios</h1>\n<p>Strong n° 4523 <i>Prononciation [sad-doo-kah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sadducéens (Angl. Sadducees) = « les justes »\n<ol>\n<li>un parti religieux parmi les Juifs du temps de Christ, qui niaient que la loi orale soit une révélation de Dieu aux Israélites, et jugeaient que seule la loi écrite devait être obligatoire sur la nation, comme autorité divine. Ils niaient les doctrines suivantes :\n<ol type=\"a\">\n<li>la résurrection du corps</li>\n<li>l'immortalité de l'âme</li>\n<li>l'existence des esprits et des anges</li>\n<li>la prédestination divine, à laquelle ils opposaient le libre arbitre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαδδουκαιος - Σαδδουκαῖος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (5)</li>\n</ul>\n</td></tr>\n</table>","G4524":"<h1>Sadok</h1>\n<p>Strong n° 4524 <i>Prononciation [sad-oke']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sadok (Angl. Sadoc) = « juste, droit »\n<ol><li>un descendant de Zorobabel dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαδωκ</font> &lt; צדוק - <font face=\"Georgia\">Σαδώκ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G4525":"<h1>saino</h1>\n<p>Strong n° 4525 <i>Prononciation [sah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>remuer la queue\n<ol type=\"a\">\n<li>de chiens</li>\n</ol>\n</li>\n<li>métaph.\n<ol type=\"a\">\n<li>flatter, aduler, être servile</li>\n<li>remuer (l'esprit de quelqu'un)\n<ol>\n<li>agréablement</li>\n<li>agiter, déranger, troubler, émouvoir</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαίνω</b> <span>(<i>f</i>. σανῶ <span>[ᾰ]</span> <i>ao</i>. ἔσηνα, <i>pf. inus. ; f. pass</i>. σανθήσομαι)</span><br><b>   I</b> remuer la queue en signe de joie : <i>abs</i>. OD. <i>16, 6 ;</i> ἀμφί τινα, OD. <i>10, 217,</i> tourner autour de qqn en remuant la queue ; σ. οὐρῇ, OD. <i>17, 302 ;</i> HÉS. <i>Th. 771 ; ou</i> οὐράν, SOPH. <i>fr. 619,</i> remuer la queue ; <i>fig</i>. σ. πρός τινα, PD. <i>P. 2, 151,</i> montrer sa joie en abordant qqn, accueillir qqn avec amitié ; πρός τι, PD. <i>O. 4, 7, ou avec l’acc</i>. τι, LUC. <i>M. cond. 20,</i> accueillir qqe ch. avec des démonstrations de joie ;<br><b>   II</b> <i>p. suite, tr. :</i><br><b>      1</b> flatter <i>ou</i> caresser, comme font les chiens en remuant la queue ; τινά, PD. <i>P. 1, 100,</i> caresser <i>ou</i> flatter qqn ; μόρον, ESCHL. <i>Sept. 383, 704,</i> flatter la mort pour la fléchir ; παιδός με σαίνει φθόγγος, SOPH. <i>Ant. 1214,</i> la voix de mon fils caresse (<i>càd</i>. arrive jusqu’à) mon oreille ; <i>abs</i>. SOPH. <i>fr. 902 ;</i><br><b>      2</b> calmer (la douleur) ESCHL. <i>Ch. 420 ;</i> tromper, SOPH. <i>fr. 508 ;</i><br><b>      3</b> émouvoir, troubler, <i>acc</i>. EUR. <i>Ion 685, etc. ;</i> σαίνεσθαι ἐν ταῖς θλίψεσιν, NT. <i>1Thess. 3, 3,</i> se laisser troubler dans les afflictions.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. dor</i>. ἔσανα <span>[σᾱ]</span> PD. <i>O. 4, 4 ; P. 1, 52 ;</i> LYC. <i>1444</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαινω - σαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4526":"<h1>sakkos</h1>\n<p>Strong n° 4526 <i>Prononciation [sak'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un sac\n<ol type=\"a\">\n<li>un réceptacle pour garder ou transporter diverses choses, telles argent, nourriture, etc.</li>\n<li>un tissu pour le voyage, une étoffe noire faite spécialement de poils d'animaux</li>\n<li>un vêtement de ce matériau, et revêtant la personne comme un sac, qui était sensé être porté (ou posé sur la tunique à la place du manteau) par les gens en deuil, les pénitents, ceux qui suppliaient, et également par ceux qui menaient une vie austère, comme les prophètes Hébreux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάκκος</b>, <i>att</i>. <b>σάκος, ου (ὁ) :<br>   I</b> étoffe grossière de poil de chèvre, <i>d’où :</i><br><b>      1</b> manteau grossier, SPT. <i>Esaï. 50, 3 ; Sir. 25, 17 ;</i> NT. <i>Apoc. 6, 12 ;</i> PLUT. <i>M. 239</i> c ;<br><b>      2</b> sac de pénitent, cilice, SPT. <i>Gen. 37, 34 ;</i> NT. <i>Luc. 10, 13 ;</i> JOS. <i>B.J. 2, 12, 5 ;</i><br><b>      3</b> sac, bourse, HDT. <i>9, 80 ;</i> AR. <i>Ach. 745, Lys. 1211 ;</i><br><b>      4</b> filtre, HIPPON. <i>fr. 57 ;</i><br><b>   II</b> <i>p. anal</i>. barbe longue et épaisse, AR. <i>Eccl. 502</i>.<br><span><b><span class=\"arrow\"></span></b> σάκος, AR. <i>Ach. 822, Eccl. 502. Dans les inscr. att</i>. σάκος, CIA. <i>2, add. 834, b, 1, 73, 74 (329 av. J.C.) et</i> σάκκος, CIA. <i>2, 62 (357 av. J.C.), v. Meisterh. p. 73, 5, a</i>.<br><span><b>Étym</b>. <i>emprunt sémit. ; cf. hébr</i>. śaq.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σακκος</font> &lt; שק - <font face=\"Georgia\">σάκκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4527":"<h1>Sala</h1>\n<p>Strong n° 4527 <i>Prononciation [sal-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sala (Salah) = « pousse, bourgeon »\n<ol><li>le fils d'Arpacschad, et père d'Eber</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλα</font> &lt; שלח - <font face=\"Georgia\">Σαλά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4528":"<h1>Salathiel</h1>\n<p>Strong n° 4528 <i>Prononciation [sal-ath-ee-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salathiel (Shealtiel) = « j'ai demandé à Dieu »\n<ol><li>le fils de Jéchonias dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλαθιηλ</font> &lt; שלתיאל - <font face=\"Georgia\">Σαλαθιήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4529":"<h1>Salamis</h1>\n<p>Strong n° 4529 <i>Prononciation [sal-am-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salamine (Salmis) = « agité »\n<ol><li>une grande ville à l'extrémité est de l'île de Chypre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σαλαμίς</b>, <i>mieux que</i> <b>Σαλαμίν, ῖνος (ἡ)</b> <span>[ᾰᾰῑ]</span> Salamine :<br><b>      1</b> <i>î. du golfe Saronique, (auj</i>. Salamína, <i>anc</i>. Koúlouri) IL. <i>2, 577 ; 7, 199 ;</i> PD. <i>P. 1, 148, etc. ;</i> ESCHL. <i>Pers. 273, etc. ;</i> SOPH. <i>Aj. 135, etc. ;</i> HDT. <i>7, 90, etc. ;</i> THC. <i>1, 137 ; etc. ;</i> XÉN. <i>Hell. 2, 2, 9 ;</i><br><b>      2</b> <i>v. de Chypre (auj</i>. ruines près d’Áyios Séryios-Yeni Boğaziçi) <i>fondée par Teucer de Salamine,</i> HH. <i>9, 4 ;</i> HDT. <i>4, 162 ;</i> THC. <i>1, 112, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. Σαλαμίς, HDT. <i>7, 141, etc. ;</i> SOPH. <i>Aj. 596, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλαμις - Σαλαμίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4530":"<h1>Saleim</h1>\n<p>Strong n° 4530 <i>Prononciation [sal-ime']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salim = « agitation »\n<ol><li>un endroit proche des eaux d'Enon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλειμ - Σαλείμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4531":"<h1>saleuo</h1>\n<p>Strong n° 4531 <i>Prononciation [sal-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un mouvement produit par les vents, les orages, les vagues, etc\n<ol type=\"a\">\n<li>agiter ou secouer</li>\n<li>faire chanceler ou vaciller</li>\n<li>secouer correctement, d'une mesure remplie en secouant son contenu</li>\n</ol>\n</li>\n<li>secouer, renverser\n<ol type=\"a\">\n<li>jeter à bas de son état de sécurité et bonheur</li>\n<li>remuer, agiter l'esprit, déranger quelqu'un</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαλεύω</b> <span>[ᾰ]</span> <span>(<i>f</i>. σαλεύσω, <i>ao</i>. ἐσάλευσα, <i>pf. inus. ; pass. f</i>. σαλευθήσομαι, <i>ao</i>. ἐσαλεύθην, <i>pf</i>. σεσάλευμαι)</span><br><b>   I <i>tr</i>.<br>      1</b> agiter, secouer, ébranler, <i>acc. :</i> πτέρυγα, EUR. <i>Cycl. 434,</i> agiter ses ailes ; ἀγκύρας, PYTHAG. (STOB. <i>Fl. 1, 29</i>) ébranler des ancres ; πέδον, LYC. <i>475,</i> ébranler le sol ; <i>en parl. d’un tremblement de terre,</i> ANTH. <i>11, 83 ; fig</i>. τὴν δόξαν, PLUT. <i>M. 1123</i> f, ébranler <i>ou</i> ruiner la réputation de qqn ; τινὰ ἐκ θεμελίων, SPT. <i>Sap. 4, 19,</i> ébranler qqn sur ses fondements et le renverser ; <i>d’où au pass</i>. être agité, secoué, ébranlé, <i>en parl. de la terre,</i> ESCHL. <i>Pr. 1080 ; cf</i>. PLAT. <i>Tim. 79</i> e ; ARSTT. <i>Mech. 27, 1 ;</i> NT. <i>Matth. 24, 29, etc. ; de la marche mal assurée des gens ivres,</i> ANTH. <i>11, 26, etc. ;</i><br><b>      2</b> secouer pour tasser, <i>d’où</i> remplir tout à fait (une mesure) NT. <i>Luc. 6, 38 ;</i><br><b>      3</b> mettre en mouvement, faire changer de place (un cheval) <i>acc</i>. ANTH. <i>11, 83, 1 ; 259, 1 ;</i><br><b>   II <i>intr.</i></b> être agité, <i>d’où :</i><br><b>      1</b> se balancer en marchant, HPC. <i>283</i> c ; TH. <i>Lass. 11 ; particul</i>. marcher d’une allure prétentieuse, se pavaner, XÉN. <i>Cyr. 2, 4, 6 ;</i> ALCIPHR. <i>3, 28 ;</i><br><b>      2</b> <i>en parl. d’un navire à l’ancre,</i> être agité d’un mouvement de roulis, XÉN. <i>Œc. 8, 17 ;</i> POLYEN <i>2, 2, 7 ;</i> SYN. <i>163</i> d, <i>164</i> a ; <i>d’où</i> être à l’ancre ; <i>fig</i>. σ. ἐπὶ φίλοις, DÉMOPH. <i>Sent. 40, p. 42,</i> se reposer sur ses amis, <i>litt</i>. s’ancrer à ses amis ; <i>cf</i>. PLUT. <i>Demetr. 38 ;</i> HLD. <i>1, 26 ;</i> σ. ἐπὶ τῶν ἐλπίδων, HLD. <i>1, 9,</i> se reposer sur les espérances ; <i>d’où avec un acc</i>. σ. ἐπί τινι τὸν βίον, τὰς ἐλπίδας, MACAR. (<i>Villois. Anecd. 2, 60</i>) ; HLD. <i>2, 33 ;</i> EUM. <i>93</i> a, faire reposer sur qqe ch. sa vie, ses espérances ;<br><b>      3</b> <i>fig</i>. être agité, <i>càd</i>. troublé, incertain, vacillant, <i>en parl. d’une ville dans la détresse,</i> SOPH. <i>O.R. 23 ;</i> EUR. <i>Rhes. 249 ; en parl. de pers</i>. SOPH. <i>El. 1074 ;</i> PLAT. <i>Leg. 923</i> b, <i>etc. ;</i><br><b>      4</b> <i>p. ext. en parl. d’un discours, d’un entretien,</i> rouler sur (<i>cf. lat</i>. versari) <i>avec</i> ἐν <i>et le dat</i>. SEXT. <i>P. 1, 65</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy. au sens pass</i>. σαλεύσομαι, SIB. <i>3, 675 ; 714, 751</i>.<br><span><b>Étym</b>. σάλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαλευω - σαλεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 14 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Actes (4)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G4532":"<h1>Salem</h1>\n<p>Strong n° 4532 <i>Prononciation [sal-ame']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salem = « paix »\n<ol><li>le lieu où Melchisédek fut roi, et semble-t-il, l'ancien nom de Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλεμ</font> &lt; שלם - <font face=\"Georgia\">Σαλήμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4533":"<h1>Salmon</h1>\n<p>Strong n° 4533 <i>Prononciation [sal-mone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salmon = « un vêtement »\n<ol><li>le père de Boaz dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλμων</font> &lt; שלמון - <font face=\"Georgia\">Σαλμών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4534":"<h1>Salmone</h1>\n<p>Strong n° 4534 <i>Prononciation [sal-mo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salmone = « vêtu »\n<ol><li>un promontoire à pic sur la pointe est de l'île de Crète</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλωμη - Σαλμώνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4535":"<h1>salos</h1>\n<p>Strong n° 4535 <i>Prononciation [sal'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'agitation ou gonflement de la mer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σάλος, ου (ὁ)</b> <span>[ᾰ]</span> agitation, <i>particul. :</i><br><b>      1</b> agitation du sol, tremblement de terre, EUR. <i>I.T. 46 ;</i><br><b>      2</b> agitation des flots, SOPH. <i>Ph. 271 ;</i> EUR. <i>I.T. 1443, etc. ; au plur</i>. EUR. <i>Or. 994 ; p. ext</i>. lieu d’ancrage, mouillage, POL. <i>1, 53, 10 ;</i> DS. <i>3, 44 ;</i> M. RUBR. <i>p. 5 ; fig</i>. agitation, trouble, SOPH. <i>O.R. 22 ;</i> LYS. <i>107, 28 ; d’où</i> détresse, PLUT. <i>Alex. 32 ; particul</i>. trouble de l’âme, inquiétude, SPT. <i>Sir. 40, 5</i>.<br><span><b>Étym</b>. <i>pré-grec ; cf</i>. *σάλη, σαλεύω ; <i>lat</i>. salum.</span><br><br>\n➁ <b>σάλος, εος-ους (τὸ)</b> <span>[ᾰ]</span> <i>lacon. c</i>. θάλεα ; <i>au dat. pl. poét</i>. σάλεσσιν, ALCM. <i>10</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαλως - σάλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4536":"<h1>salpigx</h1>\n<p>Strong n° 4536 <i>Prononciation [sal'-pinx]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une trompette</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάλπιγξ, ιγγος (ἡ) :<br>   I</b> trompette droite, IL. <i>18, 219 ;</i> ESCHL. <i>Eum. 568 ;</i> SOPH. <i>Aj. 18 ;</i> EUR. <i>Ph. 1377, etc. ;</i> ὑπὸ τῆς σάλπιγγος, AR. <i>Ach. 1001 ;</i> ὑπὸ σάλπιγγος, SOPH. <i>El. 711 ;</i> ἀπὸ σάλπιγγος, XÉN. <i>Hipp. 3, 12, etc. ;</i> παρὰ σάλπιγγα, XÉN. <i>Eq. 9, 11,</i> au signal <i>ou</i> au son de la trompette ; <i>p. ext. :</i><br><b>      1</b> signal <i>ou</i> son de la trompette, ARSTT. <i>Rhet. 3, 6, 7 ;</i><br><b>      2</b> qui sonne de la trompette, <i>ép. d’Athèna, à Argos,</i> LYC. <i>915, 986 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> sorte de coquillage marin, ARCHIL. <i>192 (168</i>) ;<br><b>      2</b> autre n. du poisson σάλπη, ARSTT. <i>H.A. 5, 9, 5</i>.<br><span><b>Étym</b>. <i>pré-grec ; pour la format. cf</i>. σῦριγξ, φόρμιγξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαλπιγξ - σάλπιγξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G4537":"<h1>salpizo</h1>\n<p>Strong n° 4537 <i>Prononciation [sal-pid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sonner de la trompette</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαλπίζω</b> <span>(<i>f</i>. σαλπιῶ, <i>ao</i>. ἐσάλπιξα, <i>pf. inus. ; pf. pass. v. ci-dessous</i>)</span><br><b>      1</b> sonner de la trompette, <i>avec un acc. ;</i> σ. ῥυθμούς, XÉN. <i>An. 7, 3, 32,</i> marquer la mesure en sonnant de la trompette ; <i>fig</i>. ἡμέραν, LUC. <i>Oc. 114,</i> annoncer le jour comme avec une trompette, <i>en parl. du coq ;</i><br><b>      2</b> sonner, résonner, <i>en parl. de la trompette :</i> ἐπεὶ ἐσάλπιγξε, XÉN. <i>An. 1, 2, 17,</i> lorsque la trompette eut résonné ; <i>cf</i>. IL. <i>21, 388 (ao. poét</i>. σάλπιγξα) <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. σαλπιῶ, SPT. <i>Num. 10, 4 ; fut. réc</i>. σαλπίσω, NT. <i>1Cor. 15, 52 ; ao. poét</i>. ἐσάλπιγξα, ARCHIPP. (<i>Com. fr. 2, 722</i>) ; XÉN. <i>An. 1, 2, 17 (conj</i>. -ιξα) <i>ou</i> σάλπιγξα, IL. <i>21, 388 ;</i> OPP. <i>C. 2, 59 ; ao. réc</i>. ἐσάλπισα, LUC. <i>Oc. 114, etc. ; pf. pass. 3 sg</i>. σεσάλπιγκται, EUDAMONID. (STOB. <i>54, 65</i>).<br><span><b>Étym</b>. σάλπιγξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαλπιζω - σαλπίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 12 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (10)</li>\n</ul>\n</td></tr>\n</table>","G4538":"<h1>salpistes</h1>\n<p>Strong n° 4538 <i>Prononciation [sal-pis-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un joueur de trompette, un trompettiste</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαλπιστής, οῦ (ὁ)</b> <i>c</i>. σαλπικτής, POL. <i>1, 45, 13 ;</i> DH. <i>4, 17, etc</i>.<br><br>\n<b>σαλπικτής</b>, <i>mieux que</i> <b>σαλπιγκτής, οῦ (ὁ)</b> un trompette, un clairon, THC. <i>6, 69 ;</i> XÉN. <i>An. 4, 3, 29, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. seul</i>. σαλπικτής <i>du 4<sup>e</sup> siècle av. J.C. au temps de l’empire ; à partir du 1<sup>er</sup> siècle après J.C. la forme</i> σαλπιστής (<i>inscript. de 37 après J.C.) à côté de</i> σαλπικτής ; <i>v. Meisterhans p. 65, 6</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαλπιστης - σαλπιστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4539":"<h1>Salome</h1>\n<p>Strong n° 4539 <i>Prononciation [sal-o'-may]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Salomé (Angl. Salome) = « paisible »\n<ol><li>l'épouse de Zébédée et la mère de l'apôtre Jacques le Majeur et Jean</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαλωμη</font> &lt; שלמית - <font face=\"Georgia\">Σαλώμη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Marc (2)</li>\n</ul>\n</td></tr>\n</table>","G4540":"<h1>Samareia</h1>\n<p>Strong n° 4540 <i>Prononciation [sam-ar'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Samarie (Angl. Samaria) = « montagne de gué »\n<ol><li>un territoire de Palestine, qui avait Samarie comme capitale</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σαμάρεια, ας (ἡ)</b> Samarie, <i>v. de Judée,</i> POL. <i>5, 71, 11, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμαρεια</font> &lt; שמרון - <font face=\"Georgia\">Σαμάρεια</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (7)</li>\n</ul>\n</td></tr>\n</table>","G4541":"<h1>Samareites</h1>\n<p>Strong n° 4541 <i>Prononciation [sam-ar-i'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un Samaritain\n<ol type=\"a\">\n<li>un habitant de la ville de Samarie</li>\n<li>un habitant du district de Samarie, au centre de la Palestine.</li>\n</ol>\n</li>\n<li>La plupart des Juifs refusèrent très tôt de s'unir aux Samaritains sur le plan social et religieux, et cette répugnance dégénéra en antipathie intense. Les Samaritains n'étaient pas de pure race juive et pratiquaient une religion mixte. Leurs doctrines ont ressemblé à celles des Sadducéens, mais ils reçurent facilement l'évangile que leur prêcha Philippe.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμαρειτης - Σαμαρίτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>Jean (4)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4542":"<h1>Samareitis</h1>\n<p>Strong n° 4542 <i>Prononciation [sam-ar-i'-tis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une femme de Samarie, une Samaritaine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμαρειτις - Σαμαρῖτις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G4543":"<h1>Samothrake</h1>\n<p>Strong n° 4543 <i>Prononciation [sam-oth-rak'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Samothrace (Angl. Samothracia) = « la Samos de Thrace »\n<ol><li>île à 60 km au large de Thrace, dont le point culminant est à 1524 m</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σαμο·θρᾴκη, ης (ἡ)</b> <span>[ᾰᾱ]</span> Samothrace (<i>auj</i>. Samothráki) <i>î. à l’embouchure de l’Hèbre,</i> AR. <i>Pax 277 ;</i> XÉN. <i>Hell. 5, 1, 7, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Sur l’écriture</i> Σαμοθρᾴκη, <i>v. Meisterh. p. 50, § 21, 1 ; ion</i>. Σαμοθρηΐκη, HDT. <i>2, 51 ; 6, 47 ; par contr</i>. Σαμοθρῄκη, ORPH. <i>Arg. 29, 468 ; H. 38, 21</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμοθρακη - Σαμοθρᾴκη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4544":"<h1>Samos</h1>\n<p>Strong n° 4544 <i>Prononciation [sam'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Samos = « une falaise sablonneuse »\n<ol><li>île au large de l'Asie Mineure, autonome quand Paul y aborda</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σάμος, ου (ἡ)</b> <span>[ᾰ]</span> Samos :<br><b>      1</b> <i>la même que</i> Σαμοθρᾴκη, IL. <i>24, 78, 753 ;</i> Σάμος Θρηϊκίη, IL. <i>13, 12 ;</i> HH. <i>Ap. 34, m. sign. ;</i><br><b>      2</b> <i>î. de la mer Icarienne (auj</i>. Sámos, <i>turc</i> Sisam) HH. <i>Ap. 41 ;</i><br><b>      3</b> <i>anc. n. de</i> Κεφαλληνία, <i>c</i>. Σάμη, IL. <i>2, 634 ;</i> OD. <i>4, 671 ; 15, 29 ;</i><br><b>      4</b> <i>î. du Nil,</i> HÉCAT. E. BYZ. <i>v°</i> Ἔφεσος.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. dor</i>. Σάμω, THCR. <i>Idyl. 7, 40</i>.<br><span><b>Étym</b>. σάμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμος - Σάμος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4545":"<h1>Samouel</h1>\n<p>Strong n° 4545 <i>Prononciation [sam-oo-ale']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Samuel = « entendu, ou exaucé de Dieu »\n<ol><li>le fils d'Elkana et Anne, le dernier des juges, un prophète renommé, et un fondateur de l'ordre prophétique, il donna aux Juifs leurs premiers rois, Saül, David</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμουηλ</font> &lt; שמואל - <font face=\"Georgia\">Σαμουήλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4546":"<h1>Sampson</h1>\n<p>Strong n° 4546 <i>Prononciation [samp-sone']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Samson = « comme le soleil, petit soleil »\n<ol><li>un juge célèbre d'Israël renommé pour sa force physique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαμψων</font> &lt; שמשון - <font face=\"Georgia\">Σαμψών</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4547":"<h1>sandalion</h1>\n<p>Strong n° 4547 <i>Prononciation [san-dal'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une sandale, une semelle de bois ou de cuir, protégeant la plante du pied et attachée par des lanières</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σανδάλιον, ου (τὸ)</b> <span>[δᾰ]</span><br><b>      ➀ </b> <i>dim. de</i> σάνδαλον, HDT. <i>2, 91 ;</i> CRAT. (<i>Com. fr. 2, 91</i>) ;<br>\n<b>σάνδαλον, ου (τὸ)</b> <span>[δᾰ]</span><br><b>      1</b> sandale de bois, fixée par des courroies passant sur le pied, EUP. <i>2-1, 545 Meineke ; au plur</i>. HH. <i>Merc. 79, 83, 139 ;</i><br><b>      2</b> <i>sorte de poisson,</i> MATR. (ATH. <i>136</i> b) ; LUC. <i>H. conscr. 10, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Éol</i>. σάμϐαλον, SAPPH. <i>fr. 98 Bgk ;</i> ANTH. <i>6, 267</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span></span>\n<br><b>      ➁</b> <i>c</i>. σανδάλιος, ORIB. <i>180 ;</i><br>\n<b>σανδάλιος, ου (ὁ)</b> <span>[δᾰ]</span> <i>sorte de bandage,</i> ORIB. <i>84</i>.\n<br><b>      ➂</b> <i>sorte de poisson,</i> ALCIPHR. <i>1, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σανδαλιον - σανδάλιον</font>\n<br><br>vient d'un dérivé de sandalon (une « sandale »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4548":"<h1>sanis</h1>\n<p>Strong n° 4548 <i>Prononciation [san-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un panneau, une planche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σανίς, ίδος (ἡ)</b> <span>[ᾰῐδ]</span> ais, planche, <i>d’où</i> toute construction en planches :<br><b>      1</b> porte, EUR. <i>Or. 1221 ; touj. au pl. dans Hom</i>. battants de porte, OD. <i>2, 344, etc. ;</i> IL. <i>9, 583 ; 12, 121, 453, 461, etc. ;</i><br><b>      2</b> échafaudage, plate-forme en bois, OD. <i>21, 51 ;</i><br><b>      3</b> plancher, <i>particul</i>. plancher de navire, EUR. <i>Hel. 1556 ; au pl</i>. pont de navire, POL. <i>1, 22, 5, 9 ;</i> LUC. <i>J. tr. 48 ; fig</i>. ANTH. <i>9, 415, 6 ;</i><br><b>      4</b> planche pour écrire, EUR. <i>Alc. 968 ; au plur</i>. planche <i>ou</i> écriteau de bois pour afficher certains avis (listes, lois, décrets, arrêts, <i>etc</i>.) ; <i>particul</i>. causes à juger, AR. <i>Vesp. 349, 848 ;</i> lois à proposer, AND. <i>11, 28 ;</i> liste de magistrats, LYS. <i>176, 9 ;</i> noms de débiteurs, DÉM. <i>791, 11 ; à Rome,</i> tables de lois, DC. <i>42, 32 ;</i><br><b>      5</b> poteau où l’on attachait les condamnés, HDT. <i>7, 33 ; 9, 120 ;</i> AR. <i>Th. 931, 940 ;</i> PLUT. <i>Per. 28</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σανις - σανίς</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4549":"<h1>Saoul</h1>\n<p>Strong n° 4549 <i>Prononciation [sah-ool']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Saul = « désiré, demandé (à Dieu) »\n<ol><li>le nom Juif de l'apôtre Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαουλ</font> &lt; שאול - <font face=\"Georgia\">Σαούλ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 6 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (9)</li>\n</ul>\n</td></tr>\n</table>","G4550":"<h1>sapros</h1>\n<p>Strong n° 4550 <i>Prononciation [sap-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pourri, putréfié</li>\n<li>corrompu par quelqu'un et plus bon à l'usage, usé</li>\n<li>de pauvre qualité, mauvais, peu propre à l'usage, sans valeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαπρός, ά, όν</b> <span>[ᾰ]</span><br><b>      1</b> pourri, moisi, gâté, HPC. <i>278, 19 ; en parl. de parties du corps (poumons,</i> HPC. <i>451, 6 ; os cariés,</i> HPC. <i>774</i> b, <i>etc.) ; d’objets divers, part. de cuir,</i> AR. <i>Vesp. 38 ; de poisson,</i> AR. <i>Ach. 1101 ; de fleurs,</i> DÉM. <i>615, 11 ; fig</i>. vieux, usé, <i>joint à</i> ἀρχαῖος, AR. <i>Pl. 322 ; en parl. de pers</i>. AR. <i>Eccl. 884, Vesp. 1381 ;</i> PHILÉM. (<i>Com. fr. 4, 58</i>) ; MÉN. (<i>Com. fr. 4, 101</i>) ; <i>joint à</i> γέρων, AR. <i>Pax 698 ;</i><br><b>      2</b> <i>en b. part,</i> qui a un goût de pourri, <i>en parl. de vin vieux parfumé de plantes qu’on y a fait infuser,</i> AR. <i>Pl. 1086 ;</i> ALEX. <i>et</i> PHILYLL. (<i>Com. fr. 3, 460 ; 2, 865</i>).<br><span><b>Étym</b>. σήπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαπρος - σαπρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Luc (2)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4551":"<h1>Sapphira</h1>\n<p>Strong n° 4551 <i>Prononciation [sap-fi'-ray]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Saphira (Angl. Sapphira) = « belle comme un saphir »\n<ol><li>l'épouse d'Ananias</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαπφιρα - Σάπφιρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4552":"<h1>sapphiros</h1>\n<p>Strong n° 4552 <i>Prononciation [sap'-fi-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>saphir : une pierre précieuse, variété de corindon, gemme bleue transparente, de grande dureté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαπφιρος</font> &lt; ספיר - <font face=\"Georgia\">σάπφιρος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4553":"<h1>sargane</h1>\n<p>Strong n° 4553 <i>Prononciation [sar-gan'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une corde tressée, une bande, un bandeau</li>\n<li>un panier, une corbeille faite de cordes, un couffin</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαργάνη, ης (ἡ)</b> <span>[γᾰ]</span><br><b>      1</b> <i>c</i>. ταργάνη, ESCHL. <i>Suppl. 788 ;</i><br><b>      2</b> osier tressé, <i>d’où</i> corbeille, TIMOCL. (<i>Com. fr. 3, 606</i>) ; LUC. <i>Lex. 6 ;</i> NT. <i>2Cor. 11, 33</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαργανη - σαργάνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4554":"<h1>Sardeis</h1>\n<p>Strong n° 4554 <i>Prononciation [sar'-dice]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sardes (Angl. Sardis) = « les rouges », « princes de joie »\n<ol><li>une cité luxuriante d'Asie Mineure, la capitale de la Lydie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σάρδεις, εων, εσι, εις (αἱ)</b> Sardes (<i>auj</i>. Sart) <i>capitale de la Lydie,</i> ESCHL. <i>Pers. 45, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat</i>. Σάρδεσι, ESCHL. <i>Pers. 321. Ion</i>. Σάρδιες, ANTH. <i>7, 709, etc. ; par contr</i>. Σάρδις <span>[ῑ]</span> HDT. <i>5, 102 ; gén</i>. Σαρδίων, HDT. <i>1, 7, etc. ; dat</i>. Σάρδισι <span>[δῐ]</span> HDT. <i>5, 101, etc. ; acc</i>. Σάρδιας, CALL. <i>Dian. 248 ; par contr</i>. Σάρδις <span>[ῑ]</span> HDT. <i>1, 27</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαρδεις - Σάρδεις</font>\n<br><br>pluriel de dérivation incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G4555":"<h1>sardinos</h1>\n<p>Strong n° 4555 <i>Prononciation [sar'-dee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>sardoine, cornaline, sardius, variétés de calcédoine que les Grecs appelaient sardios et aussi sardion. Cette pierre précieuse est appelée cornaline quand elle de couleur rouge transparent, comme la chair, d'où son nom, et on appelle sardoine celle qui est de couleur rouge brun</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαρδῖνος, ου (ὁ)</b> <i>c</i>. σαρδίνη EPÆNÉT. (ATH. <i>328</i> f).<br><br>\n<b>σαρδίνη</b>, <i>v</i>. σαρδήνη.<br>\n<b>σαρδήνη, ης (ἡ)</b> sardine, GAL. <i>6, 402 vulg. ; conj</i>. σαρδίνη.<br><br>\n<u>Mot apparenté</u> : <b>σάρδιον, ου (τὸ)</b> pierre précieuse rouge et transparente, <i>càd</i>. la cornaline ; <i>ou</i> brune, <i>càd</i>. la sarde, AR. <i>fr. 309, 13 Dind. ;</i> PLAT. <i>Phæd. 110</i> d ; TH. <i>Lap. 8 et 23, etc</i>.<br><span><b>Étym</b>. Σάρδεις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαρδινος - σάρδινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4556":"<h1>sardios</h1>\n<p>Strong n° 4556 <i>Prononciation [sar'-dee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une sardoine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάρδιον, ου (τὸ)</b> pierre précieuse rouge et transparente, <i>càd</i>. la cornaline ; <i>ou</i> brune, <i>càd</i>. la sarde, AR. <i>fr. 309, 13 Dind. ;</i> PLAT. <i>Phæd. 110</i> d ; TH. <i>Lap. 8 et 23, etc</i>.<br><span><b>Étym</b>. Σάρδεις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαρδιος - σάρδιον</font>\n<br><br>adjectif venant d'une base incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4557":"<h1>sardonux</h1>\n<p>Strong n° 4557 <i>Prononciation [sar-don'-oox]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un sardonyx, sorte de calcédoine différente de la sardoine. De structure analogue à celle de l'onyx (agate fine), mais elle présente des veines de cornaline (rouges) et des raies blanches, brun clair, ou noires</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαρδ·όνυξ, υχος (ὁ)</b> <span>[ῠχ]</span> sardoine, <i>pierre précieuse,</i> PHILÉM. (<i>Com. fr. 4, 66</i>) ; PLUT. <i>M. 1160</i> f, <i>etc. ;</i> JOS. <i>A.J. 3, 7, 5 ;</i> ANTH. <i>1, 116, etc</i>.<br><span><b>Étym</b>. σάρδιον, ὄνυξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαρδονυξ - σαρδόνυξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4558":"<h1>Sarepta</h1>\n<p>Strong n° 4558 <i>Prononciation [sar'-ep-tah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sarepta = « lieu du fondeur, de l'orfèvre, raffinerie »\n<ol><li>ville Phénicienne entre Tyr et Sidon, mais plus près de Sidon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαρεπτα</font> &lt; צרפתה - <font face=\"Georgia\">Σάρεπτα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4559":"<h1>sarkikos</h1>\n<p>Strong n° 4559 <i>Prononciation [sar-kee-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de la chair, charnel\n<ol type=\"a\">\n<li>ayant la nature de la chair, c.à.d. sous l'autorité de l'appétit animal\n<ol>\n<li>gouverné par la simple nature humaine, non par l'esprit de Dieu</li>\n<li>ayant son siège dans la nature animale, ou élevé dans cette nature</li>\n<li>humain : avec l'idée inclue de dépravation, de corruption</li>\n</ol>\n</li>\n<li>appartenant à la chair\n<ol>\n<li>au corps : relatif à la naissance, à la lignée, etc</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαρκικός, ή, όν :<br>      1</b> de chair, ARSTT. <i>H.A. 10, 2, 7 ;</i><br><b>      2</b> qui concerne la chair, charnel, NT. <i>Rom. 7, 14, etc. ;</i> CLÉM. <i>1, 288 Migne ;</i><br><b>      3</b> adonné à la chair, charnel, ANTH. <i>1, 107</i>.<br><span>•<i> Cp</i>. -ώτερος, ARSTT. <i>l. c</i>.<br><span><b>Étym</b>. σάρξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαρκικος - σαρκικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4560":"<h1>sarkinos</h1>\n<p>Strong n° 4560 <i>Prononciation [sar'-kee-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de chair, constitué ou composé de chair</li>\n<li>appartenant au corps (matériau terrestre et périssable)</li>\n<li>entièrement voué à la chair, enraciné dans la chair, charnel</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάρκινος, η, ον</b> <span>[ῐ]</span><br><b>      1</b> de chair, HIPPARQ. (STOB. <i>Fl. 108, 81</i>) ; PLAT. <i>Leg. 906</i> c ; ARSTT. <i>H.A. 1, 11, 12 ;</i> THCR. <i>Idyl. 21, 66 ; fig</i>. PLUT. <i>M. 79</i> c ;<br><b>      2</b> rempli de chair, charnu, AR. <i>fr. 504 ;</i> ARSTT. <i>Nic. 3, 9, 3 ;</i> POL. <i>39, 2, 7 ;</i><br><b>      3</b> <i>p. suite,</i> sensuel, NT. <i>Hebr. 7, 16</i>.<br><span><b>Étym</b>. σάρξ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαρκινος - σάρκινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4561":"<h1>sarx</h1>\n<p>Strong n° 4561 <i>Prononciation [sarx]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la chair (la substance du corps vivant, qui recouvre les os, et qui est irriguée par le sang) de l'homme et des animaux</li>\n<li>le corps\n<ol type=\"a\">\n<li>le corps d'un homme</li>\n<li>utilisé pour l'origine naturelle ou physique\n<ol>\n<li>ce qui est né de génération naturelle</li>\n</ol>\n</li>\n<li>la nature sensuelle de l'homme, « la nature animale »\n<ol>\n<li>sans aucune suggestion de dépravation</li>\n<li>la nature animale avec ses désirs impérieux qui incitent au péché</li>\n<li>la nature physique de l'homme sujette aux souffrances</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>une créature vivante (parce que possédant un corps de chair) que ce soit homme ou animal</li>\n<li>la chair, qui dénote la nature humaine, la nature terrestre de l'homme séparé de l'influence divine et de là prompt au péché et à l'opposition à Dieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάρξ, σαρκός (ἡ) :<br>   I</b> chair de l’homme et des animaux, <i>particul. :</i><br><b>      1</b> chair, <i>p. opp. au sang,</i> HPC. <i>237, 13 ; aux intestins et aux os,</i> OD. <i>9, 293, etc. ;</i> EUR. <i>Med. 1200, etc. ; dans Hom. au plur</i>. IL. <i>8, 380 ; 13, 832, etc. ;</i> OD. <i>11, 219, etc. ; excepté</i> OD. <i>19, 450 ; chez les Att. au sg</i>. SOPH. <i>Ph. 1157 ;</i> PLAT. <i>Tim. 60</i> b, <i>etc. ; ou au plur</i>. ESCHL. <i>Sept. 1035, etc. ;</i> PLAT. <i>Phæd. 96</i> d, <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> le corps, <i>p. opp. à l’âme,</i> ESCHL. <i>Sept. 622, etc. ;</i> EUR. <i>H.f. 1269, etc. ;</i> PLUT. <i>M. 107</i> f ; <i>p. ext</i>. l’homme <i>en gén</i>. NT. <i>1Petr. 1, 24 ;</i><br><b>      3</b> la chair considérée comme aliment, EUR. <i>Med. 1189, etc. ; au plur</i>. morceaux de chair <i>ou</i> de viande, ESCHL. <i>Ag. 1097, etc. ;</i><br><b>   II</b> <i>p. anal</i>. chair d’une plante, <i>càd</i>. la partie moelleuse <i>ou</i> la pulpe de la plante, TH. <i>C.P. 6, 8, 5, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. poét</i>. σάρκεσσιν, IL. <i>8, 380, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαρξ - σάρξ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n147 fois dans 126 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (4)</li>\n<li>Luc (2)</li>\n<li>Jean (13)</li>\n<li>Actes (3)</li>\n<li>Romains (26)</li>\n<li>1 Corinthiens (11)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (18)</li>\n<li>Ephésiens (9)</li>\n<li>Philippiens (5)</li>\n<li>Colossiens (9)</li>\n<li>1 Timothée (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (7)</li>\n<li>2 Pierre (2)</li>\n<li>1 Jean (2)</li>\n<li>2 Jean (1)</li>\n<li>Jude (3)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G4562":"<h1>Sarouch</h1>\n<p>Strong n° 4562 <i>Prononciation [sar-ooch']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Seruch (Serug) = « un scion, une jeune branche »\n<ol><li>le fils de Ragau (Rehu) dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαρουχ</font> &lt; שרוג - <font face=\"Georgia\">Σερούχ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4563":"<h1>saroo</h1>\n<p>Strong n° 4563 <i>Prononciation [sar-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>balayer, nettoyer par balayage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σαρόω-ῶ</b> <span>[ᾰ]</span> balayer, <i>acc</i>. NT. <i>Luc. 15, 8 ;</i> ARTÉM. <i>2, 33 ; au pass</i>. NT. <i>Matth. 12, 44, etc. ; fig</i>. LYC. <i>389</i>.<br><span><b>Étym</b>. σάρος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σαροω - σαρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4564":"<h1>Sarrha</h1>\n<p>Strong n° 4564 <i>Prononciation [sar'-hrah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sara (Sarah) = « princesse »\n<ol><li>l'épouse d'Abraham</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαρρα</font> &lt; שרה - <font face=\"Georgia\">Σάρρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4565":"<h1>Saron</h1>\n<p>Strong n° 4565 <i>Prononciation [sar'-one]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Saron (Sharon) = « plaine ou plateau »\n<ol><li>une région de plateaux s'étendant de Césarée de Palestine à Joppé, abondante en bons pâturages et célèbre pour sa fertilité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαρων</font> &lt; שרון - <font face=\"Georgia\">Σαρ(ρ)ων</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4566":"<h1>Satan</h1>\n<p>Strong n° 4566 <i>Prononciation [sat-an']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Satan = « adversaire, ennemi »\n<ol>\n<li>adversaire (quelqu'un qui s'oppose à un autre par ses desseins ou son action), le nom donné :\n<ol type=\"a\">\n<li>au prince des mauvais esprits, l'adversaire invétéré de Dieu et de Christ\n<ol>\n<li>il incite à l'apostasie contre Dieu et au péché</li>\n<li>pervertissant les hommes par ses ruses</li>\n<li>il est dit que les adorateurs d'idoles sont sous son autorité</li>\n<li>par ses démons il peut prendre possession des hommes et leur infliger toutes sortes de maladies</li>\n<li>avec l'aide de Dieu, il est vaincu</li>\n<li>au retour de Christ depuis les cieux, il sera lié de chaînes pour mille ans, puis reviendra sur terre avec un plus grand pouvoir, et peu après sera livré au châtiment éternel</li>\n</ol>\n</li>\n<li>un homme ressemblant à Satan</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σατᾶν (ὁ)</b> <i>indécl</i>. ennemi, adversaire, SPT. <i>3Reg. 11, 14 et 23 ; particul</i>. l’ennemi par excellence, Satan, NT. <i>2Cor. 12, 7, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαταν</font> &lt; שטן - <font face=\"Georgia\">Σατάν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4567":"<h1>Satanas</h1>\n<p>Strong n° 4567 <i>Prononciation [sat-an-as']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>adversaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σατανᾶς, ᾶ</b>, <i>voc</i>. <b>ᾶ (ὁ)</b> <i>c</i>. Σατᾶν NT. <i>Matth. 4, 10, etc. ; Marc. 1, 13, etc. ; Luc. 10, 18 ; 2Cor. 2, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σατανας</font> &lt; שטן - <font face=\"Georgia\">Σατανᾶς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n35 fois dans 32 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (6)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G4568":"<h1>saton</h1>\n<p>Strong n° 4568 <i>Prononciation [sat'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un type de mesure de produits secs (farine, grain ...), d'environ 12 litres</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σάτον, ου (τὸ)</b> <i>mesure hébraïque valant 1 muid (modius) ½ romain ou 24 setiers (sextarii</i>) JOS. <i>A.J. 9, 4, 5 ;</i> NT. <i>Matth. 13, 33, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σατον - σάτον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4569":"<h1>Saulos</h1>\n<p>Strong n° 4569 <i>Prononciation [sow'-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Saul = « désiré, demandé (à Dieu) »\n<ol><li>le nom Juif de l'apôtre Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σαῦλος, ου (ὁ)</b> Saül, <i>premier n. de l’apôtre Paul,</i> NT. <i>Ap. 7, 58</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σαυλος</font> &lt; שאול - <font face=\"Georgia\">Σαῦλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 17 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (17)</li>\n</ul>\n</td></tr>\n</table>","G4570":"<h1>sbennumi</h1>\n<p>Strong n° 4570 <i>Prononciation [sben'-noo-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>éteindre, étancher\n<ol type=\"a\">\n<li>du feu ou de choses en feu\n<ol>\n<li>être éteint</li>\n</ol>\n</li>\n<li>métaph. éteindre, supprimer, étouffer\n<ol>\n<li>de l'influence divine</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σϐέννυμι</b> <span>(<i>f</i>. σϐέσω, <i>ao.1</i> ἔσϐεσα, <i>ao.2</i> ἔσϐην, <i>pf. inus. ; pass. ao</i>. ἐσϐέσθην, <i>pf</i>. ἔσϐεσμαι)</span><br><b>      1</b> éteindre, <i>acc</i>. HDT. <i>2, 66 ;</i> PD. <i>P. 1, 8 ;</i> A. RH. <i>4, 668 (dans Hom. en ce sens à l’act. seul, le cps</i>. κατασϐέννυμι) ; <i>au pass</i>. être éteint, s’éteindre, IL. <i>9, 471 ;</i> TH. <i>Ign. 61 ; p. anal. en parl. d’inflammation, de pustules,</i> s’amortir, disparaître, HPC. <i>400, 52, etc. ; en parl. de pers</i>. mourir, SIM. <i>Epigr. 180 Bgk, etc. ;</i><br><b>      2</b> <i>en parl. de liquides,</i> dessécher, <i>acc</i>. ARSTT. <i>H.A. 3, 21, 4, etc. ; au pass</i>. se sécher, se dessécher, <i>en parl. de sang,</i> PLUT. <i>M. 49</i> d ; <i>de sources,</i> ANTH. <i>9, 128 ;</i> αἶγες σϐεννύμεναι, HÉS. <i>O. 588,</i> chèvres qui n’allaitent plus ;<br><b>      3</b> apaiser, calmer : κύματα, AR. <i>Av. 778,</i> les flots ; τὴν θερμότητα, ARSTT. <i>Meteor. 1, 10, 4,</i> atténuer la chaleur ; δίψαν, A. RH. <i>3, 1349,</i> apaiser la soif ; <i>en parl. de sentiments, de passions :</i> χόλον, IL. <i>9, 678, etc. ; en prose :</i> τὸν θυμόν, PLAT. <i>Leg. 888</i> a, éteindre <i>ou</i> apaiser la colère ; <i>au pass</i>. s’apaiser, se calmer : ἔσϐη οὖρος, OD. <i>3, 182,</i> le vent s’apaisa ; s’affaiblir, s’atténuer : τὸ μάχιμον σϐεννύμενον ὑπὸ γήρως, PLUT. <i>Pomp. 8,</i> l’humeur batailleuse éteinte par la vieillesse.<br><span><b><span class=\"arrow\"></span></b> <i>Act. fut. poét</i>. σϐέσσω, ORACL. (HDT. <i>8, 77</i>) ; THCR. <i>Idyl. 23, 26. Ao. poét. inf</i>. σϐέσσαι, IL. <i>9, 678 ; 16, 621. Moy. ao. 3 sg. poét</i>. σϐέσσατο, Q. SM. <i>1, 795</i>.<br><span><b>Étym</b>. <i>p</i>. *σϐέσ-νυμι, <i>de la R. indo-europ</i>. *(s)g<sup>w</sup>es-, éteindre.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σβεννυμι - σβέννυμι</font>\n<br><br>probablement forme prolongée d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4571":"<h1>se</h1>\n<p>Strong n° 4571 <i>Prononciation [seh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>toi, tu</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σέ</b>, <i>acc. sg. du pron</i>. .<br>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σε - σέ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n193 fois dans 176 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (29)</li>\n<li>Marc (14)</li>\n<li>Luc (37)</li>\n<li>Jean (29)</li>\n<li>Actes (39)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (2)</li>\n<li>Philippiens (1)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (4)</li>\n<li>Tite (4)</li>\n<li>Philémon (3)</li>\n<li>Hébreux (8)</li>\n<li>2 Jean (2)</li>\n<li>3 Jean (3)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G4572":"<h1>seautou</h1>\n<p>Strong n° 4572 <i>Prononciation [seh-ow-too']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>toi-même, te</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεαυτοῦ, ῆς</b> (<i>neutre inus., v. ci-dessous) par contract</i>. <b>σαυτοῦ, ῆς</b>, <i>us. seul. au sg., pron. réfléchi de la 2<sup>e</sup> pers</i>. de toi-même, à toi-même, toi-même, PD. <i>fr. 64 ;</i> HDT. <i>1, 45, 108 ;</i> ATT. ; οἱ σαυτοῦ, XÉN. <i>Cyr. 3, 1, 16,</i> les tiens, tes parents ; γνῶθι σεαυτόν (<i>v</i>. γιγνώσκω) connais-toi toi-même ; <i>dans Hom. touj. et souv. dans les Att. les deux pronoms sont séparés :</i> σοῦ αὐτοῦ, σοὶ αὐτῷ, σὲ αὐτόν, <i>poét</i>. σ' αὐτόν ; <i>au pl. on emploie les deux pron. distincts :</i> ὑμῶν αὐτῶν, de vous-mêmes, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Neutre inus., excepté à l’acc. sg</i>. σεαυτό, EUR. <i>fr. 694 Nauck ; décl. ion</i>. σεωϋτοῦ, σεωϋτῷ, <i>etc</i>. HDT. <i>ll. cc. ; gén. éol</i>. σαύτω, ALC. <i>84 (75), 98 (76) Bgk</i>.<br><span><b>Étym</b>. σύ, αὐτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεαυτου - σεαυτοῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n40 fois dans 39 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (3)</li>\n<li>Luc (6)</li>\n<li>Jean (8)</li>\n<li>Actes (3)</li>\n<li>Romains (5)</li>\n<li>Galates (1)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4573":"<h1>sebazomai</h1>\n<p>Strong n° 4573 <i>Prononciation [seb-ad'-zom-ahee</i>]</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>craindre, avoir peur</li>\n<li>honorer religieusement, adorer, rendre un culte</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεϐάζω</b>, CLÉM. <i>Protr. p. 33, d’ord. moy</i>. <b>σεϐάζομαι</b> <span>(<i>fut</i>. σεϐασθήσομαι, <i>ao</i>. ἐσεϐάσθην, <i>pf. inus</i>.)</span> éprouver une crainte religieuse, <i>d’où tr. :</i><br><b>      1</b> craindre par un scrupule religieux, <i>acc</i>. IL. <i>6, 167, 417 ;</i><br><b>      2</b> vénérer, <i>acc</i>. ORPH. <i>Arg. 560 ;</i> NT. <i>Rom. 1, 25</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. moy. 3 sg. épq</i>. σεϐάσσατο, IL. <i>6, 167. Ao</i>. ἐσεϐάσθην <i>au sens act</i>. ANTH. <i>7, 122 ;</i> SIB. <i>4, 405 ; 8, 46 ; au sens pass</i>. ANTH. <i>8, 477</i>.<br><span><b>Étym</b>. σέϐας.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεβαζομαι - σεβάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4574":"<h1>sebasma</h1>\n<p>Strong n° 4574 <i>Prononciation [seb'-as-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout ce qui est honoré religieusement, objet d'adoration, de culte\n<ol type=\"a\">\n<li>de temples, autels, statues, images idolâtres</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σέϐασμα, ατος (τὸ) :<br>      1</b> <i>pass</i>. objet d’adoration <i>ou</i> de vénération, DH. <i>1, 30 ;</i> NT. <i>Ap. 17, 23 ;</i> CLÉM. <i>696 ;</i><br><b>      2</b> <i>act</i>. culte, DH. <i>5, 1 ;</i> CLÉM. <i>829</i>.<br><span><b>Étym</b>. σεϐάζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεβασμα - σέβασμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4575":"<h1>sebastos</h1>\n<p>Strong n° 4575 <i>Prononciation [seb-as-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>Auguste : vénérable, qui impose le respect</li>\n<li>Nom du premier empereur romain\n<ol type=\"a\">\n<li>appelé César Auguste dans le N.T.</li>\n<li>un titre d'honneur qui était donné à certaines légions, ou cohortes, ou bataillons, pour leur valeur</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεϐαστός, ή, όν :<br>      1</b> digne de respect, vénéré, <i>ou</i> vénérable, DH. <i>2, 75 ;</i><br><b>      2</b> <i>p. suite,</i> auguste, <i>en parl. des empereurs romains,</i> HDN <i>1, 16, 9, etc. ;</i> STR. <i>156, 578 ;</i> PAUS. <i>3, 11, 4 ;</i> NT. <i>Ap. 25, 21 ;</i> HDN <i>2, 10, etc. ;</i> ὁ Σεϐαστός, LUC. <i>Salt. 34, etc</i>. l’Empereur : ἡ Σεϐαστή.<br><span><b>Étym</b>. <i>vb. de</i> σεϐάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεβαστος - σεβαστός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4576":"<h1>sebomai</h1>\n<p>Strong n° 4576 <i>Prononciation [seb'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>révérer, adorer, vénérer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σέϐω</b> <span>(<i>act. seul. prés. et impf</i>. ἔσεϐον ; <i>pass. seul. ao. au sens moy</i>. ἐσέφθην) :</span><br><b>      1</b> vénérer, honorer, <i>particul. en parl. du respect pour les dieux ;</i> σ. θεούς, ESCHL. <i>Sept. 596 ;</i> XÉN. <i>Mem. 4, 4, 19,</i> honorer les dieux ; <i>cf</i>. ESCHL. <i>Eum. 22 ;</i> SOPH. <i>Ant. 777 ; de même, en parl. du respect pour les choses divines,</i> SOPH. <i>Aj. 713 ; pour les parents,</i> SOPH. <i>O.C. 1377 ; pour les rois,</i> SOPH. <i>Aj. 667, etc. ; au sens religieux, pour les suppliants,</i> ESCHL. <i>Eum. 151 ; rar. de la part d’une divinité,</i> EUR. <i>Hipp. 896 ; avec l’inf. :</i> ὑϐρίζειν ἐν κακοῖσιν οὐ σέϐω, ESCHL. <i>Ag. 712,</i> je ne respecte pas, <i>càd</i>. je n’approuve pas qu’on soit arrogant dans le malheur ; <i>au pass</i>. être honoré, SOPH. <i>O.C. 760 ;</i><br><b>      2</b> <i>abs</i>. honorer les dieux, être pieux, ESCHL. <i>Eum. 725, 897 ;</i> SOPH. <i>Ant. 744 ;</i> THC. <i>2, 53 ;</i><br><b><i>Moy</i>. σέϐομαι</b> <span>(<i>f. réc</i>. σεϐήσομαι)</span><br><b>      1</b> <i>dans Hom</i>. éprouver un sentiment de pudeur, de crainte religieuse, <i>d’où</i> craindre les dieux, IL. <i>4, 242, etc. ; joint à</i> τιμῶν, PLAT. <i>Leg. 729</i> c ; <i>à</i> φοϐεῖσθαι, PLAT. <i>Leg. 798</i> c ; <i>avec l’acc</i>. PLAT. <i>Leg. 798</i> b ; <i>avec l’inf</i>. craindre de, ESCHL. <i>Pers. 694 ;</i> PLAT. <i>Tim. 69</i> d, <i>etc. ; avec un part. m. sign</i>. PLAT. <i>Phædr. 250</i> e ;<br><b>      2</b> <i>après Hom</i>. vénérer, honorer, <i>acc. particul</i>. honorer les dieux, <i>acc</i>. ESCHL. <i>Suppl. 921, etc. ;</i> ὡς θεὸν σ. τινα, PLAT. <i>Phædr. 251</i> a, honorer qqn comme un dieu ; <i>cf</i>. PD. <i>P. 6, 25 ;</i> HDT. <i>1, 66, etc. ; dans les Livres saints,</i> honorer Dieu, NT. <i>Ap. 13, 40 ; 16, 14 ; de même</i> honorer un roi, ESCHL. <i>Pr. 937 ; en gén</i>. honorer un ami, SOPH. <i>O.C. 187 ;</i> un hôte, SOPH. <i>Ph. 1163 ;</i> les hommes, ESCHL. <i>Pr. 543 ; en parl. de choses (mystères,</i> AR. <i>Th. 948 ; livres,</i> HDT. <i>3, 128, etc</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. 3 pl. dor</i>. σέϐοντι, PD. <i>O. 14, 12 ; ao. pass. au sens act</i>. ἐσέφθην, SOPH. <i>fr. 175 Dind. ;</i> PLAT. <i>Phædr. 254</i> b, <i>etc. ; fut. réc</i>. σεϐήσομαι, DL. <i>7, 120</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *tieg<sup>w</sup>-, abandonner ; <i>cf</i>. σέϐας, εὐσεϐής, δυσσεϐής, σεμνός, <i>sscr</i>. tyajati, <i>et, pour le sens originel</i> « s’enfuir », <i>le causatif</i> σοϐέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεβομαι - σέβω</font>\n<br><br>vient apparemment d'un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (8)</li>\n</ul>\n</td></tr>\n</table>","G4577":"<h1>seira</h1>\n<p>Strong n° 4577 <i>Prononciation [si-rah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lien, une corde</li>\n<li>une chaîne</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σειρά, ᾶς (ἡ)</b> lien :<br><b>      1</b> corde, IL. <i>23, 115 ;</i> OD. <i>22, 175, 192 ;</i><br><b>      2</b> chaîne, IL. <i>8, 19, 25 ;</i> PLAT. <i>Theæt. 153</i> c ;<br><b>      3</b> lasso, <i>corde à nœuds coulants que les Scythes et les Parthes lançaient au cou de leurs ennemis,</i> HDT. <i>7, 85 ;</i> PAUS. <i>1, 21, 5 ;</i><br><b>      4</b> maladie des chevaux, <i>c</i>. σειρίασις, HIPPIATR.<br><span><b><span class=\"arrow\"></span></b> <i>Épq. et ion</i>. σειρή, HOM. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *tuerH-, saisir, capturer, enclore.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σειρα - σειρά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4578":"<h1>seismos</h1>\n<p>Strong n° 4578 <i>Prononciation [sice-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une secousse, une commotion</li>\n<li>une tempête</li>\n<li>un tremblement de terre, ébranlement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεισμός, οῦ (ὁ)</b> ébranlement, commotion, PLAT. <i>Phil. 33</i> e, <i>Leg. 790</i> e, <i>etc. ;</i> σ. γῆς, EUR. <i>H.f. 862 ;</i> THC. <i>3, 87 ;</i> σ. χθονός, EUR. <i>I.T. 1166 ; ou simpl</i>. σεισμός, HDT. <i>4, 28, etc. ;</i> THC. <i>1, 23 ;</i> SOPH. <i>O.C. 95 ;</i> AR. <i>Eccl. 791, etc</i>. tremblement de terre.<br><span><b>Étym</b>. σείω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεισμος - σεισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 12 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G4579":"<h1>seio</h1>\n<p>Strong n° 4579 <i>Prononciation [si'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>secouer, agiter, faire trembler\n<ol type=\"a\">\n<li>des hommes : être rempli de frémissements, trembler de peur</li>\n<li>métaph. agiter l'esprit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σείω</b> <span>(<i>f</i>. σείσω, <i>ao</i>. ἔσεισα, <i>pf. inus. ; pass. ao</i>. ἐσείσθην, <i>pf</i>. σέσεισμαι)</span><br><b>A <i>tr</i>.<br>   I</b> <i>au propre :</i> secouer, agiter, <i>particul. :</i><br><b>      1</b> agiter, <i>en parl. d’un objet qu’on tient (des rênes,</i> SOPH. <i>El. 713 ; une branche,</i> EUR. <i>Bacch. 308, etc</i>.) ; <i>d’où</i> agiter l’égide, IL. <i>15, 321 ;</i> une javeline, IL. <i>3, 345 ; 5, 563 ; 13, 135, etc. ;</i> un bouclier, AR. <i>Lys. 563, etc. ;</i><br><b>      2</b> secouer un joug, <i>en parl. de chevaux qui courent,</i> OD. <i>3, 486 ;</i> une chevelure, une crinière, <i>etc</i>. ANACR. <i>49, etc. ; d’où au pass</i>. être agité, flotter, <i>en parl. de cheveux,</i> AR. <i>Lys. 1312 ;</i> THCR. <i>Idyl. 5, 91, etc. ;</i> agiter convulsivement, EUR. <i>Ion 1204, etc. ;</i><br><b>      3</b> ébranler, <i>en parl. d’un tremblement de terre :</i> σείει ὁ θεός (<i>s.-e</i>. τὴν γῆν) XÉN. <i>Hell. 4, 7, 4 ;</i> AR. <i>Lys. 1142,</i> la divinité ébranle la terre, <i>d’où impers. :</i> ἔσεισε, THC. <i>4, 52,</i> il y eut un tremblement de terre ; <i>cf</i>. ARSTD. <i>t. 1, 318 ;</i> PHILSTR. <i>Im. 475 ; au pass</i>. être ébranlé, vaciller, trembler, IL. <i>20, 59 ;</i> HÉS. <i>Th. 680 ;</i> EUR. <i>I.T. 46, etc. ;</i><br><b>      4</b> secouer dans un crible, tamiser, MOSCHION <i>p. 274 ;</i> HSCH. <i>et</i> PHOT. <i>p. 512, 22 ;</i><br><b>   II</b> <i>fig</i>. ébranler, troubler, agiter (une ville, une maison, <i>etc.) acc</i>. PD. <i>P. 4, 484 ;</i> SOPH. <i>Ant. 163, 583 ;</i> EUR. <i>H.f. 905, etc. ;</i> τὴν κεφαλήν, HPC. <i>80</i> a, ébranler la tête ; τὸν ἐγκέφαλον σεσεῖσθαι, AR. <i>Nub. 1276,</i> avoir le cerveau ébranlé, la raison troublée ; <i>de même, en parl. des sentiments qui agitent l’âme,</i> PLAT. <i>Tim. 43</i> d, <i>etc. ; en mauv. part :</i> σείειν καὶ συκοφαντεῖν, ANT. <i>146, 21,</i> ébranler et menacer de dénonciation ceux qui ont des comptes à rendre, <i>càd</i>. chercher à leur faire acheter à prix d’argent le silence des orateurs ; <i>en gén</i>. harceler, presser, tourmenter, <i>acc</i>. PLAT. <i>Eryx. 897</i> d, <i>etc. ;</i><br><b>B <i>intr.</i></b> s’agiter, se remuer : τῇ οὐρᾷ, XÉN. <i>Cyn. 3, 4,</i> remuer la queue ; <i>p. suite,</i> flatter, ES. <i>278 de Furia ;</i><br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐσεισάμην)</span><br><b>   I <i>tr. :</i><br>      1</b> agiter, secouer (la tête, SOPH. <i>Ant. 291 ;</i> des ailes, THCR. <i>Idyl. 13, 13, etc</i>.) ;<br><b>      2</b> brandir, lancer (une pierre) AR. <i>Ach. 344 ;</i><br><b>   II <i>intr.</i></b> s’agiter, <i>en parl. d’Hèra sur son trône,</i> IL. <i>8, 199 ; en parl. de choses (panache,</i> IL. <i>13, 805 ; espalier dont les feuilles semblent s’agiter,</i> HÉS. <i>Sc. 298 ; branche,</i> CALL. <i>Ap. 1 ; dents qui branlent,</i> HDT. <i>6, 107 ; langue en mouvement,</i> PLAT. <i>Crat. 426</i> e ; <i>lueur tremblante,</i> DS. <i>18, 27, etc</i>.).<br><span><b><span class=\"arrow\"></span></b> <i>Prés</i>. σίω, ANACR. <i>l. c. Impf. poét</i>. σεῖον, OD. <i>3, 486. Pass. impf. 3 sg. poét</i>. σείετο, IL. <i>13, 805 ; 3 pl. épq</i>. ἐσσείοντο, IL. <i>20, 59. Moy. ao. 3 sg. poét</i>. σείσατο, IL. <i>8, 199</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *tuei(s)-, exciter, étinceler ; <i>cf</i>. σείριος, <i>sscr</i>. tvéṣati.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σειω - σείω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4580":"<h1>Sekoundos</h1>\n<p>Strong n° 4580 <i>Prononciation [sek-oon'-dos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Second (Angl. Secundus) = « le deuxième »\n<ol><li>un Chrétien Thessalonicien</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σεκουνδος - Σεκοῦνδος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4581":"<h1>Seleukeia</h1>\n<p>Strong n° 4581 <i>Prononciation [sel-yook'-i-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Séleucie (Angl. Seleucia) = « lumière blanche »\n<ol><li>une cité de Syrie proche de l'embouchure de l'Oronte, à environ 25 km d'Antioche</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σελεύκεια, ας (ἡ)</b> Séleukeia (Séleucie) <i>n. de diverses v. d’Asie, particul. v. près du Tigre,</i> PLUT. <i>Luc. 22, Crass. 17, 21, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σελευκεια - Σελεύκεια</font>\n<br><br>vient de Seleukos (Seleucus, un roi Syrien)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4582":"<h1>selene</h1>\n<p>Strong n° 4582 <i>Prononciation [sel-ay'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la lune</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σελήνη, ης (ἡ) :<br>   I</b> la lune, IL. <i>8, 555, etc. ;</i> σ. πλήθουσα, IL. <i>18, 484 ; ou</i> πεπληρωμένη, HLD. <i>7, 8,</i> pleine lune ; νουμηνία κατὰ σελήνην, THC. <i>2, 28,</i> le commencement du mois lunaire, <i>p. opp. au mois du calendrier ;</i> ἐν σελήνῃ, A. TAT. <i>3, 2 ;</i> πρὸς τὴν σελήνην, AND. <i>6, 18 ;</i> XÉN. <i>Hell. 1, 5, 9 ;</i> εἰς τὴν σελήνην, ESCHN. <i>67, 35,</i> à la clarté de la lune ; ἡ ἐκ τῆς σελήνης νόσος, EL. <i>N.A. 14, 27,</i> la maladie causée par l’influence de la lune, <i>càd</i>. l’épilepsie ; <i>au plur. seul en poésie, au sens du singul</i>. EUR. <i>Hel. 114 ;</i> DP. <i>720 ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> πέμματα σελήνης, ALCIPHR. <i>2, 4 ; ou abs</i>. σελῆναι, EUR. <i>fr. 352 Nauck,</i> gâteaux ronds en forme de lune ;<br><b>      2</b> table ronde à trois pieds, ASCLÉPIOD. (ATH. <i>489</i> c) ;<br><b>      3</b> <i>sorte de plante,</i> PLUT. <i>M. 1161</i> b ;<br><b>      4</b> couronne que forme la partie dénudée d’une tête chauve, SYN. <i>74</i> c.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σελάνα <span>[ᾱᾱ]</span>, PD. <i>O. 11 (10), 92 ;</i> EUR. <i>Tr. 1075 ;</i> THCR. <i>Idyl. 2, 10 ; 21, 19, etc. ; éol</i>. σελάννα, SAPPH. <i>fr. 3 Bgk ; cf</i>. κρήνη <i>et</i> κράννα.<br><span><b>Étym</b>. <i>p</i>. *σελασνᾱ, <i>v</i>. σέλας.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεληνη - σελήνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4583":"<h1>seleniazomai</h1>\n<p>Strong n° 4583 <i>Prononciation [sel-ay-nee-ad'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être influencé par la lune, ou lunatique, être devin ou sorcier</li>\n<li>être épileptique\n<ol type=\"a\">\n<li>l'épilepsie étant supposée influencée par les phases de la lune. Mais ce sens peut être mis en doute, selon la connaissance qu'avaient les Grecs de l'épilepsie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεληνιάζω</b>, être épileptique, <i>d’où</i> être devin <i>ou</i> sorcier, MAN. <i>4, 81 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. NT. <i>Matth. 4, 24 ; 17, 15 ; cf. Marc. 9, 17 ; Luc. 9, 39</i>.<br><span><b>Étym</b>. σελήνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεληνιαζομαι - σεληνιάζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G4584":"<h1>Semei</h1>\n<p>Strong n° 4584 <i>Prononciation [sem-eh-ee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sémeï (Shimei) = « renommée, ou l'Eternel a écouté »\n<ol><li>le père de Mattathias dans la généalogie de Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σεμει</font> &lt; שמעי - <font face=\"Georgia\">Σεμεΐν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4585":"<h1>semidalis</h1>\n<p>Strong n° 4585 <i>Prononciation [sem-id'-al-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la plus fine farine de blé, de froment</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεμίδαλις, εως (ἡ)</b> <span>[ῐᾱ]</span> fleur de la farine du froment, HPC. <i>356, 28 ; 405, 39 ;</i> AR. <i>fr. 364 Dind</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén</i>. σεμιδάλεος, ARCHESTR. (ATH. <i>112</i> b) ; σεμιδάλιδος, STRATT. (<i>Com. fr. 2, 764</i>) ; <i>acc</i>. σεμίδαλιν, HERMIPP. <i>et</i> MÉN. (<i>Com. fr. 2, 408 ; 4, 222</i>).<br><span><b>Étym</b>. <i>cf. lat</i>. simila, similago.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεμιδαλις - σεμίδαλις</font>\n<br><br>probablement d'origine étrangère</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4586":"<h1>semnos</h1>\n<p>Strong n° 4586 <i>Prononciation [sem-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vénérable, auguste, révérend, noble</li>\n<li>être vénéré pour son caractère, honorable\n<ol type=\"a\">\n<li>de personnes</li>\n<li>de faits</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεμνός, ή, όν :<br>   I</b> vénérable, auguste, saint, <i>primit. en parl. de pers. ou de choses divines,</i> HH. <i>28, 5, etc. ;</i> PD. <i>O. 5, 43, etc. ;</i> ESCHL. <i>Suppl. 145, etc. ;</i> SOPH. <i>Tr. 765, etc. ;</i> λόγος, HDT. <i>7, 6,</i> parole sainte, oracle ; βίος, EUR. <i>Ion 56,</i> vie consacrée à un dieu ; δόμος, PD. <i>N. 1 fin,</i> demeure sainte, temple (d’Apollon) ; σεμνόν τι πράττειν, EUR. <i>Tr. 447,</i> jouir d’une brillante fortune ; σεμνὰ (<i>dor</i>.) θεός, l’auguste divinité, <i>càd</i>. Dèmèter, HH. <i>12, 1 ;</i> la Terre, HH. <i>29, 16 ;</i> Hèkatè, PD. <i>P. 3, 140, etc. ; de même</i> σεμνός <i>en parl. d’Apollon,</i> ESCHL. <i>Sept. 800 ; de Poséidon,</i> SOPH. <i>O.C. 55, etc. ;</i> σεμναὶ θεαί, SOPH. <i>O.C. 90, 459 ;</i> THC. <i>1, 126 ; ou simpl</i>. σεμναί, les augustes déesses, <i>càd</i>. Dèmèter et Korè, HH. <i>Cer. 477 et 486 ; ou</i> les Euménides, ESCHL. <i>Eum. 383, 1041 ;</i> EUR. <i>Or. 410 ; p. antiphrase :</i> τὸ σεμνὸν ὄνομα, SOPH. <i>O.C. 41,</i> le nom auguste (des Euménides) ; σεμνὴ νόσος, SCH.-A. RH. <i>1, 1019,</i> la lèpre <i>ou</i> la peste ; <i>postér. en parl. de pers. et de choses,</i> HDT. <i>2, 173 ;</i> ESCHL. <i>Ag. 519, etc. ;</i> EUR. <i>Andr. 700, etc. ;</i> XÉN. <i>Cyr. 7, 537, etc. ;</i> PLAT. <i>Phædr. 257</i> d, <i>etc. ; p. opp. à</i> φαῦλος, AR. <i>Eccl. 617 ; à</i> ταπεινός, EUR. <i>fr. 689 ; à</i> χαῦνος, PLAT. <i>Soph. 227</i> b ; <i>à</i> κομψός, XÉN. <i>Œc. 8, 9, etc. ; en parl. du style,</i> ARSTT. <i>Poet. 22, 3 ;</i> ἐπὶ τὸ σεμνὸν μιμεῖσθαι, PLAT. <i>Leg. 814</i> e, imiter dans ce qu’il y a de noble ; τὸ σεμνὸν ἀπλάστως, M. ANT. <i>1, 9,</i> le caractère noble et simple à la fois ; σεμνόν τι λέγειν, PLAT. <i>Rsp. 382</i> b, dire qqe ch. d’extraordinaire ; οὐδὲν σεμνόν, ARSTT. <i>Nic. 7, 2, 6,</i> rien d’extraordinaire, de merveilleux ; σεμνόν ἐστι, <i>avec l’inf</i>. PLAT. <i>Ax. 368</i> d, il est extraordinaire de, <i>etc. ; simpl</i>. sérieux, EUR. <i>Alc. 800 ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> grave, majestueux, imposant, XÉN. <i>Mem. 1, 2, 24, etc. ;</i> PLAT. <i>Gorg. 502</i> b, <i>etc. ;</i> τὸ σεμνόν, EUR. <i>Hipp. 1064,</i> gravité solennelle ; <i>en mauv. part :</i> fier, hautain, orgueilleux, ESCHL. <i>Ch. 975, etc. ;</i> EUR. <i>Med. 216, etc. ;</i> DÉM. <i>313, 8, etc. ;</i> σεμνὰ ἔπη, SOPH. <i>Aj. 1107,</i> paroles orgueilleuses ; σεμνοὶ λόγοι, AR. <i>Vesp. 1174,</i> discours emphatiques ; τὸ σεμνόν, EUR. <i>Hipp. 93,</i> grands airs, fierté ;<br><b>      2</b> magnifique, splendide, <i>en parl. de choses matérielles (vêtements,</i> AR. <i>Pl. 940, etc. ; maison,</i> DÉM. <i>35, 22, etc</i>.) ; σεμνὸν περιτιθέναι τινί, XÉN. <i>Cyr. 4, 5, 54,</i> parer qqn avec magnificence ; <i>famil. en parl. d’un morceau de viande, d’un poisson,</i> ARCHESTR. (ATH. <i>295</i> c) ; ARISTOPHON (<i>Com. fr. 3, 359</i>).<br><span>•<i> Cp</i>. -ότερος, ANT. <i>31, 27 ;</i> IS. <i>55, 31 ;</i> DÉM. <i>35, 22, etc. ;</i> <i>• Sup</i>. -ότατος, PLAT. <i>Phædr. 257</i> d, <i>etc</i>.<br><span><b>Étym</b>. <i>p</i>. *σεϐνός, <i>v</i>. σέϐω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεμνος - σεμνός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>1 Timothée (2)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4587":"<h1>semnotes</h1>\n<p>Strong n° 4587 <i>Prononciation [sem-not'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le trait caractéristique d'une chose ou personne qui donne droit à révérence et respect, dignité, majesté, sainteté</li>\n<li>honneur, pureté</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σεμνότης, ητος (ἡ) :<br>      1</b> gravité, majesté, EUR. <i>Bacch. 486 ; particul. en parl. de l’attitude, du maintien,</i> XÉN. <i>Cyr. 8, 3, 1 ;</i> PLAT. <i>Menex. 235</i> b ; DÉM. <i>1405, 16 ; en parl. d’une jeune fille,</i> retenue, réserve, EUR. <i>I.A. 1344 ; en parl. du style,</i> ARSTT. <i>Rhet. 3, 8, 4 ; au plur</i>. air de gravité, ISOCR. <i>136</i> c, <i>etc. ;</i><br><b>      2</b> <i>en mauv. part,</i> gravité affectée, solennité, LUC. <i>Prom. 7</i>.<br><span><b>Étym</b>. σεμνός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεμνοτης - σεμνότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (2)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4588":"<h1>Sergios</h1>\n<p>Strong n° 4588 <i>Prononciation [serg'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sergius = « né de la terre »\n<ol><li>surnommé Paulus, député ou proconsul de Chypre et converti par Paul au christianisme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σέργιος, ου (ὁ)</b> = <i>lat</i>. Sergius, <i>n. d’h. rom</i>. PLUT. <i>Ant. 9, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σεργιος - Σέργιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4589":"<h1>Seth</h1>\n<p>Strong n° 4589 <i>Prononciation [sayth]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Seth = « une compensation, un substitut »\n<ol><li>le troisième fils d'Adam et le père d'Enos (Enosch de l'A.T.)</li></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Σήθ (ὁ)</b> <i>indécl</i>. Seth, <i>n. de Typhon chez les Égyptiens,</i> PLUT. <i>Is. et Os. 41, 49, 62</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σηθ</font> &lt; שת - <font face=\"Georgia\">Σήθ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4590":"<h1>Sem</h1>\n<p>Strong n° 4590 <i>Prononciation [same]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Sem (Angl. Shem) = « nom, renommée »\n<ol><li>le fils aîné de Noé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Σημ</font> &lt; שם - <font face=\"Georgia\">Σήμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4591":"<h1>semaino</h1>\n<p>Strong n° 4591 <i>Prononciation [say-mah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner un signe, signifier, indiquer</li>\n<li>faire connaître, rendre connu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σημαίνω</b> <span>(<i>f</i>. σημανῶ <span>[ᾰ]</span> <i>ao</i>. ἐσήμηνα, <i>pf</i>. σεσήμαγκα ; <i>pass. f</i>. σημανθήσομαι, <i>ao</i>. ἐσημάνθην, <i>pf</i>. σεσήμασμαι)</span><br><b>   I <i>tr</i>.<br>      1</b> marquer d’un signe, <i>particul</i>. marquer d’un sceau, sceller, AR. <i>Lys. 1198 ;</i> ISOCR. <i>365</i> c ; DÉM. <i>999, 16, etc. ;</i> XÉN. <i>Vect. 4, 21 ;</i> PLAT. <i>Leg. 954</i> a ; PLUT. <i>Galb. 8 ;</i><br><b>      2</b> faire un signal, <i>d’où</i> donner un ordre, IL. <i>16, 172 ; 21, 445 ;</i> OD. <i>22, 450 ;</i> XÉN. <i>Cyr. 1, 2, 8 ;</i> τινί, IL. <i>10, 58 ; 17, 250,</i> à qqn ; ἐπὶ δμῳῇσι γυναιξί, OD. <i>22, 427 ;</i> στρατοῦ, IL. <i>14, 85,</i> diriger des servantes, une armée, <i>etc. ;</i> τινὶ ποιεῖν τι, ESCHL. <i>Ag. 26 ;</i> SOPH. <i>Aj. 688, O.C. 708,</i> ordonner à qqn de faire qqe ch. ; <i>avec une prop. relat. :</i> σήμαινε τί χρὴ ποιεῖν, SOPH. <i>Tr. 598,</i> ordonne ce qu’il faut faire ; <i>particul. t. milit</i>. donner un signal, faire un commandement au moyen d’un signal, <i>en parl. du chef ou de celui qui transmet le signal, abs</i>. THC. <i>2, 84 ; 7, 50 ;</i> σ. τῇ σάλπιγγι, XÉN. <i>An. 3, 4, 4 ; 4, 2, 1 ;</i> POL. <i>6, 43, 2,</i> donner un signal avec la trompette ; τὸ πολεμικόν, XÉN. <i>An. 4, 3, 29 ;</i> POL. <i>3, 96, 2 ;</i> DS. <i>17, 33,</i> donner le signal du combat ; τὸ ἀνακλητικόν, PLUT. <i>M. 236</i> e ; <i>ou</i> ἀναχώρησιν, THC. <i>5, 10,</i> donner le signal de la retraite ; <i>avec le dat. :</i> σ. τινί, HDT. <i>8, 11 ;</i> XÉN. <i>Cyr. 4, 5, 36,</i> donner un signal <i>ou</i> un ordre à une troupe ; σημαίνειν, <i>avec l’inf</i>. XÉN. <i>Cyr. 1, 4, 18, etc</i>. donner l’ordre de, <i>etc. ; avec</i> ὡς <i>et l’inf</i>. XÉN. <i>An. 2, 2, 4, m. sign. ; impers</i>. ἐσήμαινε <i>avec l’inf</i>. HDT. <i>9, 42,</i> le signal était donné, ordre était donné de, <i>etc. ; abs</i>. τοῖς Ἕλλησι ὡς ἐσήμηνε, HDT. <i>8, 11,</i> lorsque le signal fut donné aux Grecs (pour attaquer) ;<br><b>      3</b> faire savoir, faire comprendre, expliquer, révéler : τι, IL. <i>23, 358, 757 ;</i> ESCHL. <i>Ch. 667 ;</i> SOPH. <i>Ph. 37 ;</i> EUR. <i>H.f. 1218, etc</i>. qqe ch. ; <i>avec une prop. relat</i>. ESCHL. <i>Pr. 565 ; avec</i> ὅτι <i>ou</i> ὡς, ESCHL. <i>Pers. 819 ;</i> SOPH. <i>O.C. 321 ; avec un part</i>. φθόγγοι σφε σημαίνουσι δεῦρ' ὁρμωμένας, SOPH. <i>O.C. 1669,</i> des bruits de voix annoncent qu’elles se hâtent par ici ; <i>cf</i>. PLAT. <i>Leg. 626</i> e, <i>etc. ; abs</i>. ESCHL. <i>Suppl. 245, etc. ;</i> SOPH. <i>Tr. 345, etc. ; particul</i>. faire savoir, annoncer : τι, HDT. <i>8, 62 ;</i> SOPH. <i>O.R. 226, etc</i>. qqe ch. ; τι πρός τινα, EUR. <i>Hec. 217,</i> qqe ch. à qqn ; <i>avec</i> ὅτι, XÉN. <i>Cyr. 1, 4, 18 ; avec un part</i>. Κρέοντα προσστείχοντα, SOPH. <i>O.R. 79,</i> annoncer que Créon approche ; <i>avec un relat</i>. σ. ὅστις, ESCHL. <i>Pr. 619, etc</i>. faire savoir qui, <i>etc. ; abs</i>. HDT. <i>3, 106, etc. ; particul</i>. prédire l’avenir, faire comprendre la volonté des dieux, <i>abs</i>. XÉN. <i>Mem. 1, 1, 2 ; 1, 4, 9 ; An. 6, 1, 31, etc. ; p. suite,</i> présager, <i>acc</i>. XÉN. <i>Hell. 5, 4, 17 ;</i> PLAT. <i>Crat. 405</i> e ; ARR. <i>An. 7, 22, 24, etc. ;</i><br><b>      4</b> signifier, avoir une signification, <i>en parl. d’un mot,</i> PLAT. <i>Crat. 393</i> a ; POL. <i>2, 22, 1 ;</i> τὸ σημαινόμενον, ARSTT. <i>Rhet. 3, 2, 13,</i> la signification, le sens ;<br><b>   II <i>intr.</i></b> se montrer en forme de signe <i>ou</i> de symptôme, se manifester, ARSTT. <i>H.A. 4, 8 ;</i> ARÉT. <i>p. 79, 13 ; fig</i>. ὡς ἄρτι σημαίνειν ἐκ τῶν εἰρημένων μοι σφόδρα δοκεῖ, PLAT. <i>Epin. 989</i> a, comme cela justement me paraît tout à fait résulter de ce qui a été dit ;<br><b><i>Moy.</i></b> <span>(<i>f</i>. σημανοῦμαι, <i>ao</i>. ἐσημηνάμην, <i>pf</i>. σεσήμασμαι)</span><br><b>   I</b> marquer pour soi, <i>d’où :</i><br><b>      1</b> marquer d’un signe, <i>acc</i>. HDT. <i>2, 38 ;</i><br><b>      2</b> marquer de son sceau, sceller, <i>acc</i>. XÉN. <i>Cyr. 8, 2, 17 ;</i> DÉM. <i>837, 21 ; 904, 5, etc. ;</i><br><b>      3</b> <i>p. suite,</i> désigner pour soi, choisir pour soi, <i>acc</i>. POL. <i>3, 71, 7 ;</i><br><b>   II</b> conjecturer : τι, SOPH. <i>Aj. 32,</i> qqe ch. ; <i>en parl. de chiens,</i> flairer, <i>acc</i>. OPP. <i>C. 1, 454, 480 ; prov</i>. <span>ἄστροις σημαίνεσθαι</span> (τὸ δεῖπνον) EL. <i>N.A. 2, 7,</i> reconnaître son souper d’après les étoiles, <i>càd</i>. en être loin, comme le voyageur égaré qui se guide sur les étoiles pour reconnaître son chemin ; <i>cf</i>. EL. <i>N.A. 7, 48 ;</i> LIB. <i>4, 184, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. dor</i>. σαμαίνω <span>[σᾱ]</span> THCR. <i>Idyl. 17, 89. Impf. itér. 3 sg</i>. σημαίνεσκεν, Q. SM. <i>4, 193. Fut. ion</i>. σημανέω <span>[ᾰ]</span> OD. <i>12, 26 ;</i> HDT. <i>1, 75. Ao</i>. ἐσήμανα <span>[μᾱ]</span> XÉN. <i>Hell. 1, 1, 2 ; 2, 1, 15, etc. ; dans les inscr. att. part. ao. dat. sg</i>. σημήναντι, CIA. <i>5, 30, 4 (envir. 30 av. J.C</i>.) ; <i>v. Meisterh. p. 145, § 65, 6. Pf. pass. 3 sg</i>. σεσήμανται, HDT. <i>2, 125. Moy. 3 sg. ion</i>. σημανέεται, HPC. <i>7, 276</i>.<br><span><b>Étym</b>. σῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σημαινω - σημαίνω</font>\n<br><br>vient de sema (une marque, dérivation incertaine)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (3)</li>\n<li>Actes (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4592":"<h1>semeion</h1>\n<p>Strong n° 4592 <i>Prononciation [say-mi'-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un signe, une marque, un témoignage\n<ol type=\"a\">\n<li>ce par quoi une personne ou une chose se distingue des autres et qu'elle est connue</li>\n<li>un signe, in prodige, un présage, c.à.d. une chose non usuelle modifiant le cours habituel de la nature\n<ol>\n<li>de signes présageant d'événements remarquables qui doivent bientôt arriver</li>\n<li>de miracles et merveilles par lesquels Dieu authentifie les hommes qu'il envoie, ou par lesquels les hommes prouvent que la cause qu'ils plaident est celle de Dieu</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σημεῖον, ου (τὸ) :<br>   I</b> signe, <i>càd. :</i><br><b>      1</b> marque distinctive, ce à quoi on reconnaît qqn <i>ou</i> qqe ch. ; τρίαινα σ. θεοῦ, ESCHL. <i>Suppl. 218,</i> le trident qui annonce le dieu ; <i>d’où</i> trace, XÉN. <i>An. 6, 2, 2 ;</i> σ. θηρός, κυνῶν, SOPH. <i>Ant. 257,</i> trace laissée par un animal sauvage, par des chiens ; <i>p. suite,</i> indice, EUR. <i>Hipp. 514 ; particul</i>. signe précurseur, prélude, ESCHL. <i>Ag. 1355 ;</i><br><b>      2</b> preuve, THC. <i>2, 42 ;</i> SOPH. <i>O.R. 1059 ;</i> PLAT. <i>Crat. 395</i> a ; σημεῖα φαίνειν τινός, SOPH. <i>O.R. 710,</i> produire des preuves de qqe ch. ; <i>avec un part</i>. σ. φαίνεις ἐσθλὸς γεγώς, SOPH. <i>El. 24,</i> tu donnes la preuve que tu es bon (fidèle) ; σ. ἐπιδεικνύναι ὅτι, ESCHN. <i>41, 35,</i> mettre sous les yeux la preuve que, <i>etc. ; dans ces construct</i>. ὅτι <i>ou</i> ὡς <i>marque soit la chose à prouver :</i> ὅτι ἀληθῆ λέγω σημεῖον τούτου ἐπιδείξω, ESCHN. <i>41, 35,</i> que je dis la vérité, c’est ce dont je vais produire la preuve ; <i>cf</i>. XÉN. <i>Ages. 1, 15 ;</i> PLAT. <i>Tim. 71</i> e ; <i>soit la chose au moyen de laquelle on prouve :</i> σημεῖον δέ μοι, ὅτι, PLAT. <i>Rsp. 368</i> b, la preuve pour moi, c’est que, <i>etc. ;</i> σ. δὲ εἰ, DÉM. <i>525, 18,</i> en voici la preuve, c’est que si, <i>etc. ;</i> σημεῖον δέ … γάρ, ISOCR. <i>58</i> c, <i>63</i> a ; DÉM. <i>563, 6 ;</i> POL. <i>4, 44, 3, etc</i>. la preuve c’est que, <i>etc. ;</i><br><b>      3</b> signe d’en haut, prodige, présage, XÉN. <i>Cyr. 1, 6, 1 ;</i> SOPH. <i>O.C. 94 ;</i> PLAT. <i>Phædr. 244</i> c, <i>etc. ;</i> PLUT. <i>Per. 35, etc. ;</i><br><b>      4</b> signe céleste, constellation considérée comme signe des saisons, de la température, EUR. <i>Rhes. 524, Ion 1157 ;</i><br><b>      5</b> signe gravé <i>ou</i> écrit, <i>p. ext</i>. signe de reconnaissance, HDT. <i>8, 92 ;</i> empreinte d’un cachet, sceau, XÉN. <i>Hell. 5, 1, 30 ;</i> PLAT. <i>Leg. 856</i> a, <i>Theæt. 191</i> d ; scellés sur une maison, DÉM. <i>1039, 11 ;</i> ciselure <i>ou</i> sorte d’armoiries sur un bouclier, HDT. <i>1, 171 ;</i> EUR. <i>Ph. 142, 1111, 1114 ;</i> diadème, XÉN. <i>Cyr. 8, 3, 13 ;</i> inscription <i>ou</i> peinture sur un navire, THC. <i>6, 31 ;</i> EUR. <i>I.A. 255 ;</i> AR. <i>Ran. 933, etc</i>. image, portrait, ANTICLID. (ATH. <i>473</i> c) ; reproduction, figuration, DP. <i>158 ;</i> signe d’abréviation, PLUT. <i>Cato mi. 23 ;</i> ligne des équinoxes <i>ou</i> des solstices, point, POL. <i>6, 28, 2 ; particul</i>. point mathématique, ARSTT. <i>An. post. 1, 10, 3, etc. ;</i> point dans le temps, <i>càd</i>. instant, moment, ARSTT. <i>Cæl. 1, 12, 19, etc. ; t. de pros. et de mus</i>. temps, unité de temps, note, ARISTOX. <i>p. 39 ;</i><br><b>      6</b> borne (d’un champ, d’une frontière, <i>etc</i>.) DÉM. <i>932, 14 ;</i> PLUT. <i>C. Gracch. 7 ;</i> pierre milliaire, HDN <i>2, 13, 18, etc. ; d’où</i> point de bifurcation, POL. <i>6, 28, 2 ;</i><br><b>      7</b> drapeau sur la tente d’un général, XÉN. <i>8, 5, 13 ;</i> pavillon sur un vaisseau amiral, HDT. <i>8, 92 ; en gén</i>. enseigne militaire, EUR. <i>I.A. 255 ;</i> ἔξω τῶν σημείων παρέπεσθαι, XÉN. <i>Cyr. 8, 3, 19,</i> suivre à côté, en dehors des lignes (<i>litt</i>. des enseignes) ;<br><b>   II</b> signal pour faire qqe ch. HDT. <i>8, 92 ; 9, 59 ;</i> THC. <i>4, 42, 111, etc. ;</i> XÉN. <i>An. 1, 10, 12 ; Cyr. 7, 1, 4 ; 8, 5, 13, etc. ;</i> τὸ σημεῖον αἴρειν, THC. <i>1, 49,</i> lever le signal ; σ. κατασπᾶν, THC. <i>1, 63,</i> abaisser le signal ; ἀπὸ σημείου, THC. <i>3, 91 ;</i> XÉN. <i>Hell. 6, 2, 28, etc. ; au plur</i>. ἀπὸ σημείων, XÉN. <i>Hell. 6, 2, 30,</i> à un signal donné, d’après des signaux ; <i>avec un inf</i>. σ. μηκέτι ἄνω πορεύεσθαι, XÉN. <i>Cyr. 7, 1, 23,</i> signal pour ne pas continuer à s’avancer en haut ; <i>cf</i>. HDT. <i>7, 128 ; particul</i>. signal pour annoncer une délibération d’un tribunal, AR. <i>Vesp. 690 ;</i> pour ouvrir la séance de l’assemblée, AR. <i>Eccl. 6, etc. ;</i> pour lever une séance, AND. <i>6, 4, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. σημήϊον, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. σῆμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σημειον - σημεῖον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n77 fois dans 69 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (13)</li>\n<li>Marc (7)</li>\n<li>Luc (11)</li>\n<li>Jean (17)</li>\n<li>Actes (13)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G4593":"<h1>semeioo</h1>\n<p>Strong n° 4593 <i>Prononciation [say-mi-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>marquer, noter, distinguer par un marquage</li>\n<li>marquer ou noter pour soi-même</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σημειόω-ῶ</b> <span>(<i>ao</i>. ἐσημείωσα, <i>pf</i>. σεσημείωκα ; <i>pass. ao</i>. ἐσημειώθην, <i>pf</i>. σεσημείωμαι)</span><br><b>      1</b> marquer d’un signe, <i>particul</i>. de pierres milliaires, POL. <i>3, 39, 8, etc. ;</i><br><b>      2</b> <i>particul</i>. sceller, DH. <i>4, 57 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> marquer d’un signe pour soi, prendre note de, <i>acc</i>. MARCELL. <i>V. Thuc. 47 ; p. suite,</i> noter, remarquer, <i>acc</i>. TH. <i>C.P. 1, 21, 7 ;</i> POL. <i>22, 11, 12 ;</i> DH. <i>6, 1127 ;</i> σημείωσαι, ATH. <i>55</i> b ; GRAMM. (GR. COR. <i>p. 215 sq. Schæfer) (cf. lat</i>. nota bene) notez, remarquez ; τὰ σεσημειωμένα, GRAMM. <i>1257 Bekker, Anecdota græca,</i> les particularités notées comme exceptions ;<br><b>      2</b> considérer comme un signe, comme un présage, <i>acc</i>. POL. <i>5, 78, 2 ;</i> STR. <i>404</i>.<br><span><b>Étym</b>. σημεῖον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σεμειοω - σημειόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4594":"<h1>semeron</h1>\n<p>Strong n° 4594 <i>Prononciation [say'-mer-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce jour (actuel)</li>\n<li>ce qui est arrivé aujourd'hui</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σήμερον</b>, <i>att</i>. <b>τήμερον</b>, <i>adv</i>., aujourd’hui, IL. <i>7, 30 ;</i> OD. <i>17, 186, etc. ;</i> EUR. <i>Rhes. 683 ;</i> ἡ τήμερον ἡμέρα, DÉM. <i>51, 23 ; abs</i>. ἡ σήμερον (<i>s.-e</i>. ἡμέρα), PLUT. <i>Fab. 13,</i> le jour d’aujourd’hui, aujourd’hui ; τὸ τήμερον, PLAT. <i>Conv. 176</i> e, <i>m. sign. ;</i> τὸ τ. εἶναι, PLAT. <i>Crat. 396</i> d, pour aujourd’hui ; εἰς τ. PLAT. <i>Conv. 174</i> a, <i>m. sign</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. σάμερον <span>[ᾱ]</span> PD. <i>O. 6, 47 ; P. 4, 1</i>.<br><span><b>Étym</b>. <i>p</i>. *κι-άμερον, <i>de indo-europ</i>. *ḱi-, celui-ci, <i>cf</i>. ἐκεί, <i>et</i> ἡμέρα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σημερον - σήμερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n41 fois dans 40 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (1)</li>\n<li>Luc (11)</li>\n<li>Actes (9)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Hébreux (8)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4595":"<h1>sepo</h1>\n<p>Strong n° 4595 <i>Prononciation [say'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre corrompu, détruire</li>\n<li>devenir corrompu, pourri</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σήπω</b> <span>(<i>f</i>. σήψω, <i>ao. inus., pf. au sens pass. v. ci-dessous</i>)</span><br><b>      1</b> faire tomber en pourriture, ESCHL. <i>fr. 270 Dind. ;</i> PLAT. <i>Tim. 84</i> d ; <i>d’où en gén</i>. décomposer les chairs, <i>en parl. du venin du serpent,</i> ESCHL. <i>Ch. 995, etc. ; fig</i>. corrompre, gâter (les affaires d’une ville) <i>acc</i>. DH. <i>11, 37 ; abs. joint à</i> ἀπολλύασι, PLAT. <i>Theæt. 153</i> c<br><i>Pass</i>. σήπομαι <span>(<i>f</i>. σαπήσομαι) <span>[ᾰ]</span> <i>ao.2</i> ἐσάπην <span>[ᾰ]</span> <i>pf.2</i> σέσηπα)</span> se putréfier, pourrir, <i>en parl. de cadavres,</i> IL. <i>19, 27 ; 24, 414 ;</i> HÉS. <i>Sc. 152 ; en parl. du bois d’une javeline,</i> IL. <i>2, 135 ; d’un navire,</i> AR. <i>Eq. 1308 ;</i><br><b>      2</b> <i>p. suite,</i> se gangrener, se décomposer, <i>en parl. de chairs vives,</i> HDT. <i>3, 66 ; 6, 136 ;</i> PLAT. <i>Phæd. 80</i> d ; <i>en parl. du sang,</i> EUR. <i>El. 319 ;</i><br><b>      3</b> se gâter, se corrompre, <i>en parl. de l’eau,</i> HPC. <i>Aër. 285, etc. ;</i><br><b>      4</b> <i>fig. au sens mor</i>. se corrompre, MÉN. <i>4, 74 Meineke</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. post</i>. ἐσήφθην, APOLLIN. <i>Ps. 37, 10, ao.2 sbj. 3 sg. épq</i>. σαπήῃ <span>[ᾰ]</span> IL. <i>19, 27 ; pf</i>. σέσημμαι, ARSTT. <i>H.A. 10, 1, 10</i>.<br><span><b>Étym</b>. <i>incert</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σηπω - σήπω</font>\n<br><br>apparemment un verbe primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4596":"<h1>serikos</h1>\n<p>Strong n° 4596 <i>Prononciation [say-ree-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fait de soie</li>\n<li>soie, c.à.d. le produit, des vêtements de soie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σηρικός, ή, όν</b>, de soie, PLUT. <i>M. 396</i> b ; LUC. <i>Salt. 63 ;</i> DC. <i>59, 26, etc. ;</i> τὸ σηρικόν, robe de soie, NT. <i>Apoc. 18, 12 ;</i> M. RUBR. <i>49 ; au plur</i>. STR. <i>693</i>.<br><span><b>Étym</b>. Σήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σηρικος - σιρικός</font>\n<br><br>vient de Ser (tribu des Indes d'où venait la soie)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4597":"<h1>ses</h1>\n<p>Strong n° 4597 <i>Prononciation [sace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une mite, la mite des vêtements, la teigne, papillon destructeur, teigne des étoffes (tinea)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>σής (ὁ)</b> petit ver, <i>larve d’insecte,</i> PD. <i>fr. 243 ;</i> AR. <i>Lys. 731, etc. ; fig</i>. ANTH. <i>11, 322, 347</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Avec double thème :</i></span><br><b>      1</b> <i>th</i>. σε-, <i>d’où gén. pl</i>. σέων (<i>comme d’un nomin</i>. *σεύς) AR. <i>Lys. 731 ; acc. pl</i>. σέας, LUC. <i>Ind. 1, etc. ;</i><br><b>      2</b> <i>th. réc</i>. σητ-, <i>d’où gén</i>. σητός, <i>plur</i>. σῆτες, <i>etc</i>. MÉN. (<i>Com. fr. 4, 235</i>) ; ARSTT. <i>H.A. 5, 32, 1, etc</i>.</span><br><br>\n➁ <b>σῇς</b>, <i>ion. c</i>. σαῖς, <i>dat. pl. fém. de</i> .<br>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σης - σής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4598":"<h1>setobrotos</h1>\n<p>Strong n° 4598 <i>Prononciation [say-tob'-ro-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>mangé des mites ou des teignes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σητό·ϐρωτος, ος, ον</b>, mangé des vers, SPT. <i>Job 13, 28 ;</i> NT. <i>Jac. 5, 2</i>.<br><span><b>Étym</b>. σής, βιϐρώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σητοβρωτος - σητόβρωτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4599":"<h1>sthenoo</h1>\n<p>Strong n° 4599 <i>Prononciation [sthen-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre fort, fortifier\n<ol type=\"a\">\n<li>de l'âme</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>σθενόω-ῶ</b>, avoir la force de, NAZ. <i>2, 469 Migne</i>.<br><span><b>Étym</b>. σθένος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">σθενοω - σθενόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>"};
